// Gerado por scripts/gerar-roteiros.mjs a partir de atual.html, nova.html, calculadora.html e cofre.html. Não edite à mão.
export const ROTEIRO_ATUAL_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Roteiro Atual da Call</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow+Condensed:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap\">\n<style>\n/* Análise do roteiro que o time usa hoje: placar, a call como acontece, os números de 11 calls gravadas e os erros que se repetem. */\n:root {\n  color-scheme: dark;\n  --bg: #0a0a0a;\n  --bg-2: #0b0e0d;\n  --fg: #f6f6f6;\n  --muted: rgba(246, 246, 246, 0.68);\n  --faint: rgba(246, 246, 246, 0.42);\n  --line: rgba(255, 255, 255, 0.10);\n  --card: rgba(255, 255, 255, 0.04);\n  --teal: #2dd4bf;\n  --teal-ink: #052e2a;\n  --teal-wash: rgba(45, 212, 191, 0.07);\n  --teal-edge: rgba(45, 212, 191, 0.40);\n  --red: #ff2e5f;\n  --red-band: #e2063c;\n  --red-wash: rgba(255, 46, 95, 0.08);\n  --red-edge: rgba(255, 46, 95, 0.34);\n  --amber: #f5b942;\n  --amber-wash: rgba(245, 185, 66, 0.08);\n  --amber-edge: rgba(245, 185, 66, 0.36);\n  --display: \"Bebas Neue\", \"Oswald\", \"Arial Narrow\", Impact, sans-serif;\n  --body: \"Barlow Condensed\", \"Roboto Condensed\", \"Arial Narrow\", sans-serif;\n  --ui: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 19px; line-height: 1.55; -webkit-font-smoothing: antialiased; }\n.wrap { width: 100%; max-width: 1180px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n@media (min-width: 900px) { .wrap { padding-left: max(40px, env(safe-area-inset-left, 0px)); padding-right: max(40px, env(safe-area-inset-right, 0px)); } }\n.t { color: var(--teal); }\n.r { color: var(--red); }\nstrong { font-weight: 700; color: var(--fg); }\na { color: var(--teal); }\na:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; border-radius: 6px; }\n\n.band { background: var(--red-band); color: #fff; text-align: center; font-family: var(--display); letter-spacing: 0.32em; font-size: 15px; padding-block: 10px; }\n.band a { color: #fff; }\n\n.hero { border-bottom: 1px solid var(--line); background: radial-gradient(900px 520px at 85% 0%, rgba(226, 6, 60, 0.16), transparent 60%), radial-gradient(700px 480px at 0% 100%, rgba(45, 212, 191, 0.10), transparent 60%), var(--bg-2); }\n.hero .wrap { padding-block: 52px 40px; display: grid; gap: 22px; }\n.brand { font-family: var(--display); letter-spacing: 0.18em; font-size: 18px; color: var(--muted); }\n.pills { display: flex; flex-wrap: wrap; gap: 10px; }\n.pill { display: inline-flex; align-items: center; gap: 8px; font-family: var(--display); letter-spacing: 0.16em; font-size: 14px; padding: 6px 14px; border-radius: 999px; border: 1px solid var(--red-edge); color: var(--red); background: var(--red-wash); text-decoration: none; }\n.pill.teal { border-color: var(--teal-edge); color: var(--teal); background: var(--teal-wash); }\nh1 { font-family: var(--display); font-weight: 400; font-size: clamp(54px, 8vw, 104px); line-height: 0.9; letter-spacing: 0.02em; margin: 0; text-wrap: balance; }\n.lede { max-width: 66ch; font-size: 21px; color: var(--muted); margin: 0; }\n\n.score { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 1px solid var(--line); border-radius: 16px; background: var(--card); overflow: hidden; }\n.score div { padding: 16px 18px; display: grid; gap: 2px; min-width: 0; }\n.score div + div { border-left: 1px solid var(--line); }\n.score b { font-family: var(--display); font-weight: 400; font-size: 52px; line-height: 0.95; font-variant-numeric: tabular-nums; }\n.score span { font-family: var(--ui); font-size: 12.5px; color: var(--muted); line-height: 1.35; }\n.note { font-family: var(--ui); font-size: 12.5px; color: var(--faint); margin: 0; }\n\nsection.block { padding-block: 52px 8px; display: grid; gap: 20px; }\nsection.block + section.block { border-top: 1px solid var(--line); }\n.kicker { font-family: var(--display); letter-spacing: 0.2em; font-size: 15px; color: var(--faint); }\nh2 { font-family: var(--display); font-weight: 400; font-size: clamp(38px, 4.4vw, 58px); line-height: 0.95; letter-spacing: 0.02em; margin: 2px 0 0; text-wrap: balance; }\n.intro { margin: 0; max-width: 68ch; font-size: 20px; color: var(--muted); }\n\n/* a call como acontece */\n.flow { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; counter-reset: f; }\n.flow li { counter-increment: f; padding: 16px; border-radius: 14px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.flow li::before { content: counter(f); font-family: var(--display); font-size: 30px; line-height: 1; color: var(--faint); }\n.flow b { font-family: var(--display); font-weight: 400; font-size: 23px; letter-spacing: 0.03em; line-height: 1; }\n.flow span { font-size: 17px; color: var(--muted); line-height: 1.35; }\n.flow .tempo { font-family: var(--ui); font-size: 12px; color: var(--faint); }\n.flow li.bad { border-color: var(--red-edge); background: var(--red-wash); }\n.flow li.bad::before { color: var(--red); }\n\n/* a call que vendeu */\n.flow li.good { border-color: var(--teal-edge); background: var(--teal-wash); }\n.flow li.good::before { color: var(--teal); }\n.score.win b { color: var(--teal); }\n.quotes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.quotes blockquote { margin: 0; padding: 14px 18px; border-left: 3px solid var(--teal-edge); background: var(--teal-wash); border-radius: 0 12px 12px 0; font-size: 19.5px; font-style: italic; color: var(--fg); line-height: 1.4; }\n.quotes cite { display: block; margin-top: 8px; font-family: var(--ui); font-style: normal; font-size: 12.5px; color: var(--faint); }\n.atencao { margin: 0; padding: 14px 18px; border-radius: 14px; border: 1px solid var(--amber-edge); background: var(--amber-wash); font-size: 18.5px; color: var(--muted); line-height: 1.42; }\n.atencao b { font-family: var(--display); font-weight: 400; letter-spacing: 0.08em; color: var(--amber); }\n\n/* barras de aderência */\n.bars { display: grid; gap: 10px; }\n.bar { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr) 70px; gap: 16px; align-items: center; padding: 12px 16px; border-radius: 12px; border: 1px solid var(--line); background: var(--card); }\n.bar .lbl { font-size: 19px; line-height: 1.3; min-width: 0; }\n.bar .lbl small { display: block; font-family: var(--ui); font-size: 12.5px; color: var(--faint); margin-top: 2px; }\n.track { height: 12px; border-radius: 999px; background: rgba(255, 255, 255, 0.07); overflow: hidden; }\n.fill { height: 100%; border-radius: 999px; }\n.fill.good { background: var(--teal); }\n.fill.bad { background: var(--red); }\n.fill.zero { background: transparent; }\n.bar .num { font-family: var(--display); font-size: 30px; line-height: 1; text-align: right; font-variant-numeric: tabular-nums; }\n.bar.want .num { color: var(--red); }\n.bar.avoid .num { color: var(--red); }\n.legend { display: flex; flex-wrap: wrap; gap: 8px 20px; font-family: var(--ui); font-size: 12.5px; color: var(--muted); }\n.legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }\n\n/* erros */\n.errs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; counter-reset: e; }\n.err { counter-increment: e; padding: 20px 22px; border-radius: 16px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 10px; align-content: start; min-width: 0; }\n.err header { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: baseline; }\n.err header::before { content: counter(e); font-family: var(--display); font-size: 34px; line-height: 1; color: var(--red); }\n.err h3 { margin: 0; font-family: var(--display); font-weight: 400; font-size: 27px; letter-spacing: 0.03em; line-height: 1; }\n.sev { font-family: var(--ui); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; padding: 3px 8px; border-radius: 999px; white-space: nowrap; }\n.sev.alta { color: var(--red); border: 1px solid var(--red-edge); background: var(--red-wash); }\n.sev.media { color: var(--amber); border: 1px solid var(--amber-edge); background: var(--amber-wash); }\n.err p { margin: 0; font-size: 19px; color: var(--muted); line-height: 1.42; }\n.err blockquote { margin: 0; padding: 10px 14px; border-left: 3px solid var(--red-edge); background: rgba(255, 255, 255, 0.025); border-radius: 0 10px 10px 0; font-size: 18.5px; font-style: italic; color: var(--fg); }\n.err .fix { font-size: 18px; color: var(--fg); border-top: 1px solid var(--line); padding-top: 10px; }\n.err .fix::before { content: \"O certo: \"; font-family: var(--display); letter-spacing: 0.08em; color: var(--teal); }\n.err.wide { grid-column: 1 / -1; }\n\n/* tabelas */\n.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 14px; }\ntable { width: 100%; border-collapse: collapse; font-family: var(--ui); font-size: 14px; min-width: 620px; }\nth, td { text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: top; }\nth { font-weight: 600; color: var(--faint); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }\ntr:last-child td { border-bottom: 0; }\ntd.no { color: var(--red); font-weight: 600; }\ntd.ok { color: var(--teal); font-weight: 600; }\n\n.works { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.works div { padding: 16px 18px; border-radius: 14px; border: 1px solid var(--teal-edge); background: var(--teal-wash); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.works b { font-family: var(--display); font-weight: 400; font-size: 24px; letter-spacing: 0.03em; line-height: 1; color: var(--teal); }\n.works span { font-size: 17.5px; color: var(--muted); line-height: 1.38; }\n\n.cta { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; padding: 22px; border-radius: 16px; border: 1px solid var(--teal-edge); background: var(--teal-wash); }\n.cta p { margin: 0; font-size: 20px; flex: 1 1 320px; }\n.btn { font-family: var(--display); letter-spacing: 0.14em; font-size: 17px; padding: 10px 18px; border-radius: 999px; background: var(--teal); color: var(--teal-ink); text-decoration: none; white-space: nowrap; }\n\nfooter { border-top: 1px solid var(--line); margin-top: 52px; }\nfooter .wrap { padding-block: 24px 40px; font-family: var(--ui); font-size: 12.5px; color: var(--faint); display: flex; flex-wrap: wrap; gap: 8px 24px; justify-content: space-between; }\n\n@media (max-width: 980px) {\n  .flow { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .works { grid-template-columns: minmax(0, 1fr); }\n}\n@media (max-width: 720px) {\n  body { font-size: 18px; }\n  .score { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .score div:nth-child(3) { border-left: 0; }\n  .score div:nth-child(n+3) { border-top: 1px solid var(--line); }\n  .errs, .flow, .quotes { grid-template-columns: minmax(0, 1fr); }\n  .bar { grid-template-columns: minmax(0, 1fr) 56px; }\n  .bar .track { grid-column: 1 / -1; grid-row: 2; }\n}\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\n</style>\n</head>\n<body>\n\n<div class=\"band\">ANÁLISE INTERNA · TIME COMERCIAL</div>\n\n<header class=\"hero\">\n  <div class=\"wrap\">\n    <div class=\"brand\">CANAL DO ANFITRIÃO</div>\n    <div class=\"pills\">\n      <span class=\"pill\">Como a call é feita hoje</span>\n      <a class=\"pill teal\" href=\"#venda\">A call que vendeu ↓</a>\n    </div>\n    <h1>O roteiro<br><span class=\"r\">de hoje</span></h1>\n    <p class=\"lede\">O que acontece de verdade nas calls, montado a partir de <strong>17 calls gravadas</strong> (3 de 03/11 e 14 de 04 a 11/11) e das conversas de WhatsApp depois delas.</p>\n    <div class=\"score\" aria-label=\"Placar de 09 a 11/11\">\n      <div><b>26</b><span>calls marcadas de 09 a 11/11</span></div>\n      <div><b class=\"r\">10</b><span>faltaram (38%), nenhuma resgatada pelo sistema</span></div>\n      <div><b>16</b><span>aconteceram</span></div>\n      <div><b class=\"t\">1</b><span>Black vendida na própria call, a do Flávio em 11/11 (nenhum A5E; mais 1 curso de Booking)</span></div>\n    </div>\n    <p class=\"note\">Dia 11/11 fechado: 7 calls marcadas, 6 aconteceram e 1 falta (o Gerson, que não conseguiu entrar no Teams). A das 14h, do Flávio, fechou a Black na própria call (<a href=\"#venda\">veja abaixo</a>). A das 16h foi adiantada pelo WhatsApp e feita no Google Meet, fora do Teams e sem gravação. As outras vendas do dia vieram por mensagem, e uma Black na TMB (link do Breno, 15h36) entrou sem conversa nem call registrada no sistema.</p>\n  </div>\n</header>\n\n<main class=\"wrap\">\n\n  <section class=\"block\" id=\"venda\">\n    <div><span class=\"kicker\">11/11, 14h · Flávio com Breno Lima</span><h2>A call que <span class=\"t\">vendeu</span></h2></div>\n    <p class=\"intro\">Black Friday Vitalícia pelo preço de tabela, em 12x no cartão (R$ 10.796,52). O lead chegou quente: veio da live, já pensava em comprar e tinha uma trava só, o medo de pagar R$ 8 mil e não se adaptar ao curso, que o Téo anotou na ficha antes da call. O que o Flávio fez com isso:</p>\n    <div class=\"score win\" aria-label=\"A call em números\">\n      <div><b>26</b><span>minutos de call</span></div>\n      <div><b>0</b><span>desconto ou bônus extra: preço de tabela</span></div>\n      <div><b>3</b><span>vezes a garantia de 14 dias, sempre ligada à trava do lead</span></div>\n      <div><b>21</b><span>minutos do link ao pagamento</span></div>\n    </div>\n    <ol class=\"flow\">\n      <li class=\"good\"><span class=\"tempo\">0–2 min</span><b>Abre pelo lead</b><span>\"Me passa um pouco mais do seu projeto, fica à vontade.\" O lead conta dos 5 apartamentos, do plano de ir para Brasília e da dúvida dele.</span></li>\n      <li class=\"good\"><span class=\"tempo\">2–4 min</span><b>Pergunta o que já tentou</b><span>\"Algum curso foi do Rômulo?\" e \"qual oferta mais te chamou atenção?\". Descobre o medo: pagar por conteúdo que ele já viu.</span></li>\n      <li class=\"good\"><span class=\"tempo\">4–14 min</span><b>Recomenda pelo caso</b><span>\"O A5E é para quem começa; o seu caso é o Gigantes.\" Ainda é tour de módulos, mas cada um ligado à gestão para terceiros e a Brasília.</span></li>\n      <li class=\"good\"><span class=\"tempo\">15–17 min</span><b>Garantia na trava</b><span>O lead diz que tem medo de não se adaptar à didática. A resposta: 14 dias, o dobro do comum, 100% de volta.</span></li>\n      <li class=\"good\"><span class=\"tempo\">17–19 min</span><b>Comunidade</b><span>O lead diz que o grupo de WhatsApp é o que mais vale para ele. O Flávio aprofunda: 350 gestores e o Rômulo por perto, por 4 anos.</span></li>\n      <li class=\"good\"><span class=\"tempo\">20–21 min</span><b>Garantia de novo</b><span>\"Se não for o que a gente conversou, fala direto comigo que eu aciono o reembolso.\" O lead relaxa.</span></li>\n      <li class=\"good\"><span class=\"tempo\">21–24 min</span><b>Pede o fechamento</b><span>\"Fez sentido para você? Teria interesse?\" Com o sim: \"cartão ou boleto?\".</span></li>\n      <li class=\"good\"><span class=\"tempo\">24 min em diante</span><b>Link na hora</b><span>O lead quer falar com a mãe antes. O link vai pelo WhatsApp mesmo assim, e 18 min depois: \"Deu tudo certo?\". Pago às 14h46.</span></li>\n    </ol>\n    <div class=\"quotes\">\n      <blockquote>\"A gente confia nisso, que a gente te dá 14 dias de garantia. A maioria é 7 dias, né? A gente deixa 14 dias ou a gente devolve 100% do seu investimento.\"<cite>Flávio, aos 15 minutos</cite></blockquote>\n      <blockquote>\"Então assim eu fico bem mais tranquilo de experimentar, e acredito que vai dar tudo certo.\"<cite>Breno Lima, aos 20 minutos</cite></blockquote>\n    </div>\n    <p class=\"atencao\"><b>Um deslize:</b> no fim, \"esse investimento vai se pagar, você vai ver\" é promessa de resultado. Não fazia falta: o lead já tinha decidido pela garantia.</p>\n  </section>\n\n  <section class=\"block\" id=\"fluxo\">\n    <div><span class=\"kicker\">A call como acontece</span><h2>Oito partes, <span class=\"r\">nesta ordem</span></h2></div>\n    <p class=\"intro\">Os três vendedores seguem a mesma sequência. Marcada como papo de 20 minutos, a call dura de 25 a 45. O lead fala pouco e ouve muito: a apresentação dos módulos ocupa metade do tempo.</p>\n    <ol class=\"flow\">\n      <li><span class=\"tempo\">0–2 min</span><b>Abertura</b><span>\"Sou do time comercial do Rômulo, vou entender seu cenário.\"</span></li>\n      <li><span class=\"tempo\">2–5 min</span><b>2 a 5 perguntas</b><span>Sobre o imóvel e a experiência. Ninguém pergunta meta, prazo ou o que preocupa.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">3–8 min</span><b>\"Conhece o Rômulo?\"</b><span>Vem o currículo: imóveis, locações, alunos. Com números diferentes a cada vendedor.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">4–7 min</span><b>\"Dois sentimentos\"</b><span>\"No fim você vai ter dois sentimentos…\"</span></li>\n      <li class=\"bad\"><span class=\"tempo\">15–30 min</span><b>Tour pelos módulos</b><span>Hospitalidade, PriceLabs, OwnerPro, IA, imposto, terceiros, AirCover. A comunidade aparece no fim, como bônus.</span></li>\n      <li><span class=\"tempo\">antes do preço</span><b>\"Ficou alguma dúvida?\"</b><span>Checagem genérica, sem resumo do caso do lead.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">21–37 min</span><b>Preço</b><span>Já com desconto e bônus, sem o lead ter pedido. Cada vendedor parte de um valor.</span></li>\n      <li><span class=\"tempo\">23–39 min</span><b>Pedido</b><span>\"Podemos seguir com a inscrição?\" Depois do \"vou pensar\", proposta por WhatsApp e espera.</span></li>\n    </ol>\n  </section>\n\n  <section class=\"block\" id=\"numeros\">\n    <div><span class=\"kicker\">14 calls gravadas de 04 a 11/11</span><h2>O que aparece <span class=\"r\">e o que não aparece</span></h2></div>\n    <p class=\"intro\">Contagem pelas falas do vendedor nas transcrições do Teams (12 calls de venda, 10 de A5E e 2 da Black; as outras 2 foram de aluna com dúvida e uma gravação sem o nome do vendedor). Erro de transcrição pode mudar um número ou outro, não o quadro.</p>\n    <div class=\"legend\"><span><i style=\"background: var(--red)\"></i>vermelho = deveria acontecer e não acontece, ou não deveria e acontece</span></div>\n    <div class=\"bars\">\n      <div class=\"bar want\"><span class=\"lbl\">Cita a garantia de 14 dias<small>a resposta mais forte pro \"vou pensar\" e pro cônjuge; a única call que citou foi a que vendeu</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 7%\"></div></div><span class=\"num\">1/14</span></div>\n      <div class=\"bar want\"><span class=\"lbl\">Aprofunda o caso do lead<small>\"me conta mais\", rotular o problema, \"o que você já tentou?\"</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 7%\"></div></div><span class=\"num\">1/14</span></div>\n      <div class=\"bar want\"><span class=\"lbl\">Usa o cupom de R$ 2.797, o degrau certo da escada<small>nas calls de A5E</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 10%\"></div></div><span class=\"num\">1/10</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Dá o curso de Booking de bônus<small>nas calls de A5E; só deveria sair se o lead pedir mais desconto depois do R$ 2.497</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 80%\"></div></div><span class=\"num\">8/10</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Faz o tour pelos módulos</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 67%\"></div></div><span class=\"num\">8/12</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Desce para R$ 2.497 (desconto de R$ 500) sem objeção concreta<small>nas calls de A5E</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 50%\"></div></div><span class=\"num\">5/10</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Pergunta \"você conhece o Rômulo?\"</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 33%\"></div></div><span class=\"num\">4/12</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Faz o combinado dos \"dois sentimentos\"</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 33%\"></div></div><span class=\"num\">4/12</span></div>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"erros\">\n    <div><span class=\"kicker\">Os erros que se repetem</span><h2>Onde a venda <span class=\"r\">escapa</span></h2></div>\n    <div class=\"errs\">\n      <article class=\"err\">\n        <header><h3>O preço cai antes da objeção</h3><span class=\"sev alta\">alto</span></header>\n        <p>O lead nem reclamou do preço e já recebe R$ 2.497 com o Booking de presente. Quando a objeção chega, não sobra degrau: o vendedor inventa outro.</p>\n        <blockquote>\"O Anfitrião custa 3 mil reais, só que como a gente tá em Black Friday eu consigo disponibilizar 500 reais de desconto… e o curso de Booking sem custo adicional.\" (11/11, lead sem nenhuma objeção)</blockquote>\n        <p class=\"fix\">R$ 2.997 sempre primeiro. R$ 2.797 só na objeção de preço, R$ 2.497 só com trava concreta, Booking só se pedir mais.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Bônus de presente</h3><span class=\"sev alta\">alto</span></header>\n        <p>O bônus vira agrado em vez de ferramenta de fechamento. Sai antes de o lead pedir, e às vezes com justificativa pessoal.</p>\n        <blockquote>\"Vou te ofertar como bônus o curso de Booking, por você ter aceito esse bate-papo. Eu gostei muito de você.\" (10/11)</blockquote>\n        <p class=\"fix\">O bônus é o último degrau da escada, não o primeiro.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>A garantia quase nunca aparece</h3><span class=\"sev alta\">alto</span></header>\n        <p>Apareceu em 1 de 14 calls, justo na que vendeu: era a trava do lead, e ele pagou 21 minutos depois do link. Em 03/11 ela só apareceu no WhatsApp, horas depois, quando o cônjuge já tinha achado caro. É o argumento que tira o risco da mesa.</p>\n        <p class=\"fix\">\"Você tem 14 dias de garantia. A lei dá 7, a gente dá 14: é o dobro. Se não for o que eu te disse, devolvemos 100%.\"</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Promessa de ganho</h3><span class=\"sev alta\">alto</span></header>\n        <p>Número de faturamento e \"certeza\" de resultado usados como argumento. Além de proibido, vira problema se o aluno não chegar lá.</p>\n        <blockquote>\"Um de 19 metros quadrados… você consegue faturar com ele aí de 15 a 17, 18 mil.\" (10/11)</blockquote>\n        <blockquote>\"O curso realmente promete uma diária a mais, e isso é certeza que você vai ter.\" (10/11)</blockquote>\n        <p class=\"fix\">Nada de promessa de ganho nem de faturamento. A prova é o caso de aluno, contado como história.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Apresenta antes de entender</h3><span class=\"sev alta\">alto</span></header>\n        <p>Duas a cinco perguntas sobre o imóvel e depois 15 a 30 minutos de módulos. O vendedor não sabe a meta, o prazo nem o medo do lead quando chega no preço, então não tem com o que ligar o preço ao caso dele.</p>\n        <p class=\"fix\">Perguntar e resumir o caso (\"hoje você…, quer chegar em…, o que está no caminho é… É isso?\") antes de mostrar qualquer coisa.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Condições que não existem</h3><span class=\"sev alta\">alto</span></header>\n        <p>Cada vendedor cria um preço. O lead compara, e quem pagou mais se sente enganado.</p>\n        <blockquote>\"Os 2 [ingressos do Encontro], né, 697… a gente vê se consegue algum cupomzinho de desconto pra vocês.\" (11/11; a pré-venda é R$ 997 Standard e R$ 1.397 VIP)</blockquote>\n        <p>Também apareceram: cupom de R$ 800 (R$ 2.297), preço de aluno da Black para quem não é aluno, consultoria que está pausada, \"a esposa assiste no mesmo acesso\" e, em 11/11, \"R$ 2.000 eu verifico com o time técnico; se eu conseguir, a gente fecha hoje\" e \"a gente consegue ver uma condição bacana para as duas irem juntas\" (ingresso do Encontro para mãe e filha).</p>\n        <p class=\"fix\">Só a escada e as condições da tabela. Fora disso, o vendedor diz que confirma com o time antes de prometer.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>O cônjuge fica de fora</h3><span class=\"sev media\">médio</span></header>\n        <p>O cônjuge aparece em 6 das 14 calls, quase sempre na saída: \"vou ver com meu marido\", \"minha mulher está ocupada\". Em 11/11 foi a mãe, no mesmo papel, em 2 calls (\"vou conversar com a minha mãe, que faz o curso comigo\"). Ninguém convidou quem decide junto para a call.</p>\n        <p class=\"fix\">Chamar o cônjuge já na marcação. Se não veio, tratar a objeção na hora e fechar com a garantia de 14 dias.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Currículo do Rômulo no lugar da conversa</h3><span class=\"sev media\">médio</span></header>\n        <p>\"Você conhece o Rômulo?\" abre um bloco de números que muda a cada vendedor (80, 89 imóveis; 11 mil locações), e em 03/11 entraram números da empresa, que nunca podem ser citados.</p>\n        <p class=\"fix\">Uma frase só: \"Começou em 2016 alugando um quartinho… hoje administra mais de 70 imóveis.\"</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>\"Vou pensar\" sem pergunta e sem data</h3><span class=\"sev media\">médio</span></header>\n        <p>Diante do \"vou pensar\", o vendedor aceita e manda proposta por WhatsApp. Em 3 das 12 calls de venda a saída foi sem data de retorno.</p>\n        <p class=\"fix\">\"Você acha que vai melhor com isso do que sem? O que você tem medo que aconteça?\" e, se não fechar, retorno com dia e hora.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>A comunidade vira bônus</h3><span class=\"sev media\">médio</span></header>\n        <p>A comunidade de WhatsApp com o Rômulo aparece entre os minutos 15 e 24, no fim da lista de módulos. É o que o YouTube não tem, e chega quando o lead já cansou.</p>\n        <p class=\"fix\">Chamar o A5E de comunidade desde o começo e falar dela no começo da apresentação, não no fim.</p>\n      </article>\n      <article class=\"err wide\">\n        <header><h3>Quase metade falta, e ninguém resgata</h3><span class=\"sev alta\">alto</span></header>\n        <p>9 das 19 calls de 09 e 10/11 tiveram falta. Quem marcou para o mesmo dia apareceu (2 de 2); com 1 dia de antecedência, 4 de 6; com 2 ou 3 dias, 0 de 2. Das faltas, 3 foram remarcadas por fora do sistema e 6 ficaram sem contato. Em 11/11, uma call foi adiantada e feita no Google Meet: sem gravação, ela não entra na análise. A falta não é erro do vendedor, mas é a maior perda do funil hoje: cada falta é uma call que nem chega ao roteiro.</p>\n        <p>Em 11/11 apareceu outra causa: o Gerson baixou o app do Teams na hora da call, escreveu às 11h40 \"não sei bem o que fazer\" e a primeira resposta veio às 12h14, quando a call já tinha passado.</p>\n        <p class=\"fix\">Oferecer horários mais próximos, responder na hora quem escreve que não consegue entrar e remarcar quem faltou pelo próprio sistema, com o mesmo vendedor.</p>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"preco\">\n    <div><span class=\"kicker\">Preço, cupom e bônus</span><h2>Cinco preços <span class=\"r\">para o mesmo curso</span></h2></div>\n    <p class=\"intro\">O A5E custa R$ 2.997 na tabela. Nas calls e no WhatsApp, entre 03 e 11/11, ele saiu assim:</p>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th>Preço oferecido</th><th>Quando apareceu</th><th>Com bônus?</th><th>Bate com a escada?</th></tr></thead>\n        <tbody>\n          <tr><td>R$ 2.997 ou 12x R$ 299,70</td><td>Preço de partida de um dos vendedores</td><td>Booking e Sublocação citados na apresentação</td><td class=\"ok\">Sim, é o primeiro degrau</td></tr>\n          <tr><td>R$ 2.797 (cupom)</td><td>1 call em 10</td><td>Booking junto</td><td class=\"no\">Degrau certo, bônus antes da hora</td></tr>\n          <tr><td>R$ 2.497 ou 12x R$ 249,70</td><td>Preço de partida de dois vendedores, sem objeção</td><td>Booking (às vezes Booking ou Sublocação, à escolha)</td><td class=\"no\">Não: pula dois degraus</td></tr>\n          <tr><td>R$ 2.297 (cupom de R$ 800)</td><td>WhatsApp, depois do \"vou ver com meu marido\"</td><td>—</td><td class=\"no\">Não existe na escada</td></tr>\n          <tr><td>R$ 2.000 (\"se eu conseguir\")</td><td>11/11, o lead pediu e o vendedor disse que verifica com o time; foi na proposta por WhatsApp</td><td>Booking junto</td><td class=\"no\">Não existe na escada</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"funciona\">\n    <div><span class=\"kicker\">O que já funciona</span><h2>Para <span class=\"t\">manter</span></h2></div>\n    <div class=\"works\">\n      <div><b>Link na própria call</b><span>Na call que vendeu, o Flávio perguntou \"cartão ou boleto?\", mandou o link antes de desligar e voltou 18 minutos depois com \"Deu tudo certo?\". O pagamento entrou em seguida.</span></div>\n      <div><b>Retorno com data</b><span>Em 7 das 12 calls de venda a saída teve dia marcado (ex.: \"amanhã às 10h, depois de falar com a esposa\"). É assim que o lead volta.</span></div>\n      <div><b>Pagamento explicado</b><span>Parcelamento em 12 de 14 calls e boleto em 8. Ninguém sai da call sem saber como pagaria.</span></div>\n      <div><b>A IA como diferencial</b><span>A assistente que monta o plano de estudo e responde no grupo foi mostrada em 6 calls, ao vivo, e o lead reage bem.</span></div>\n    </div>\n  </section>\n\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>Fontes: transcrições das calls no Teams (03 a 11/11/2026), conversas de WhatsApp e o placar do sistema de calls. Atualizado em 11/11/2026.</span>\n    <span>Canal do Anfitrião · uso interno do time comercial</span>\n  </div>\n</footer>\n\n</body>\n</html>\n";
export const ROTEIRO_NOVA_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Roteiro Novo da Call</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700&family=Raleway:wght@400;500;600;700&family=Barlow:wght@300;400;600&family=Roboto:wght@800&display=swap\">\n<style>\n/* Visual no padrão do site do Anfitrião 5 Estrelas (anfitriao5estrelas.com.br):\n   fundo claro, coral #E23D59, teal #24757F, Poppins nos títulos, Raleway no texto,\n   Barlow fina nos rótulos e botão em pílula coral. Menu fixo à esquerda com as 8\n   etapas da call; à direita, cada etapa num card branco. */\n:root {\n  color-scheme: light;\n  --bg: #f6f6f6;\n  --card: #ffffff;\n  --ink: #333333;\n  --ink-2: #4a4a4a;\n  --muted: #69727d;\n  --line: #ececec;\n  --line-2: #dadada;\n  --coral: #e23d59;\n  --coral-dark: #c92e49;\n  --coral-wash: #fdeef1;\n  --teal: #24757f;\n  --teal-2: #2a8995;\n  --teal-light: #aadbe1;\n  --teal-wash: #eaf5f6;\n  --shadow: 0 10px 30px rgba(17, 24, 39, 0.06);\n  --title: \"Poppins\", \"Raleway\", system-ui, sans-serif;\n  --body: \"Raleway\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  --label: \"Barlow\", \"Raleway\", system-ui, sans-serif;\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--body); font-size: 18px; line-height: 1.6; -webkit-font-smoothing: antialiased; }\n.wrap { width: 100%; max-width: 1280px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n@media (min-width: 900px) { .wrap { padding-left: max(40px, env(safe-area-inset-left, 0px)); padding-right: max(40px, env(safe-area-inset-right, 0px)); } }\nstrong { font-weight: 700; color: var(--ink); }\na { color: inherit; }\na:focus-visible, button:focus-visible { outline: 3px solid var(--teal-light); outline-offset: 3px; border-radius: 8px; }\n.c { color: var(--coral); }\n\n/* topo, como o hero do site: foto do Rômulo à direita sobre fundo escuro */\n.hero { position: relative; color: #fff; background: #1c1c1c url(\"/marca/a5e-hero.webp\") right center / cover no-repeat; padding-top: env(safe-area-inset-top, 0px); }\n.hero::before { content: \"\"; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(20, 20, 20, 0.92) 0%, rgba(20, 20, 20, 0.78) 45%, rgba(20, 20, 20, 0.15) 75%, transparent 100%); }\n.hero .wrap { position: relative; padding-block: 40px 120px; display: grid; gap: 22px; max-width: 1280px; }\n.hero .logo { width: 168px; height: auto; display: block; }\n.pills { display: flex; flex-wrap: wrap; gap: 10px; }\n.pill { display: inline-flex; align-items: center; gap: 8px; font-family: var(--label); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; font-size: 13px; padding: 6px 14px; border-radius: 999px; background: rgba(255, 255, 255, 0.12); border: 1px solid rgba(255, 255, 255, 0.25); }\n.pill.coral { background: var(--coral); border-color: var(--coral); }\nh1 { font-family: var(--title); font-weight: 700; font-size: clamp(40px, 5.6vw, 68px); line-height: 1.05; letter-spacing: -0.01em; margin: 0; max-width: 13ch; }\n.lede { max-width: 56ch; font-size: 20px; color: rgba(255, 255, 255, 0.86); margin: 0; }\n.lede strong { color: #fff; }\n.postura { max-width: 60ch; display: grid; gap: 4px; padding: 16px 18px; border-radius: 14px; background: rgba(255, 255, 255, 0.10); border: 1px solid rgba(255, 255, 255, 0.22); font-size: 16.5px; color: rgba(255, 255, 255, 0.9); }\n.postura b { font-family: var(--label); font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; font-size: 12.5px; color: var(--teal-light); }\n\n/* as 8 etapas em cards brancos sobre a borda do topo */\n.closer { position: relative; z-index: 2; margin-top: -78px; display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 10px; }\n.closer a { text-decoration: none; padding: 14px 12px 14px; display: grid; gap: 2px; min-width: 0; border-radius: 14px; background: var(--card); box-shadow: var(--shadow); border: 1px solid var(--line); transition: transform 0.2s, border-color 0.2s; }\n.closer a:hover { transform: translateY(-2px); border-color: var(--coral); }\n.closer b { font-family: var(--title); font-weight: 700; font-size: 28px; line-height: 1; color: var(--coral); }\n.closer span { font-family: var(--body); font-weight: 600; font-size: 14.5px; line-height: 1.2; color: var(--ink); }\n\n/* corpo com menu */\n.layout { display: grid; grid-template-columns: 232px minmax(0, 1fr); gap: 36px; padding-block: 36px 24px; }\n.nav { position: sticky; top: calc(env(safe-area-inset-top, 0px) + 20px); align-self: start; display: grid; gap: 2px; padding: 14px; border-radius: 16px; background: var(--card); box-shadow: var(--shadow); border: 1px solid var(--line); }\n.nav .label { font-family: var(--label); font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; font-size: 12px; color: var(--muted); margin: 2px 8px 8px; }\n.nav a { display: grid; grid-template-columns: 28px minmax(0, 1fr); align-items: center; gap: 8px; padding: 8px 10px; border-radius: 10px; text-decoration: none; color: var(--ink-2); font-weight: 600; font-size: 15.5px; }\n.nav a b { font-family: var(--title); font-weight: 700; color: var(--line-2); font-size: 18px; }\n.nav a:hover { background: var(--bg); }\n.nav a.on { background: var(--coral-wash); color: var(--coral-dark); }\n.nav a.on b { color: var(--coral); }\n.nav .rule { margin-top: 12px; padding: 12px; border-radius: 12px; background: var(--teal-wash); font-size: 13.5px; color: var(--teal); line-height: 1.45; font-weight: 500; }\n.nav .rule strong { color: var(--teal); }\n\n/* etapas */\nmain { display: grid; gap: 22px; min-width: 0; }\n.stage { scroll-margin-top: 20px; display: grid; gap: 20px; padding: 32px 34px 34px; border-radius: 20px; background: var(--card); box-shadow: var(--shadow); border: 1px solid var(--line); min-width: 0; }\n.stage-head { display: grid; gap: 10px; justify-items: start; }\n.tag { display: inline-block; font-family: var(--title); font-weight: 600; font-size: 14px; letter-spacing: 0.02em; color: #fff; background: var(--coral); padding: 6px 14px; border-radius: 8px; }\n.tag.teal { background: var(--teal); }\nh2 { font-family: var(--title); font-weight: 600; font-size: clamp(30px, 3.4vw, 44px); line-height: 1.08; letter-spacing: -0.01em; margin: 0; color: var(--coral); text-wrap: balance; }\nh2 .t { color: var(--teal); }\n.intro { margin: 0; max-width: 66ch; font-size: 18.5px; color: var(--ink-2); }\n\n/* falas: balões como os do grupo de WhatsApp no site */\n.says { display: grid; gap: 12px; justify-items: start; }\n.say { margin: 0; max-width: 46ch; padding: 16px 22px 18px; border-radius: 20px 20px 20px 6px; background: var(--coral); color: #fff; font-size: 22px; line-height: 1.38; font-weight: 600; box-shadow: 0 8px 20px rgba(226, 61, 89, 0.18); }\n.say::before { content: \"FALA\"; display: block; font-family: var(--label); font-weight: 600; font-size: 11.5px; letter-spacing: 0.2em; color: rgba(255, 255, 255, 0.78); margin-bottom: 2px; }\n.say.small { font-size: 19px; max-width: 58ch; }\n.say .slot { color: #fff; border-bottom: 2px dashed rgba(255, 255, 255, 0.7); }\n.say.lead { background: #fff; color: var(--ink); border: 1px solid var(--line-2); border-radius: 20px 20px 6px 20px; box-shadow: none; justify-self: end; }\n.say.lead::before { content: \"LEAD\"; color: var(--muted); }\n\n.do, .dont { display: grid; gap: 10px; list-style: none; margin: 0; padding: 0; }\n.do li, .dont li { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 12px; align-items: start; font-size: 17.5px; color: var(--ink-2); }\n.do li::before, .dont li::before { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-family: var(--body); font-size: 13px; font-weight: 700; margin-top: 1px; }\n.do li::before { content: \"✓\"; background: var(--teal); color: #fff; }\n.dont li::before { content: \"✕\"; background: var(--coral); color: #fff; }\n.dontbox { padding: 16px 20px; border-radius: 14px; background: var(--coral-wash); display: grid; gap: 8px; }\n.kicker { font-family: var(--label); font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; font-size: 12.5px; color: var(--muted); }\n.dontbox .kicker { color: var(--coral-dark); }\n\n.example { padding: 18px 22px; border-radius: 14px; background: var(--teal-wash); border-left: 4px solid var(--teal); display: grid; gap: 4px; }\n.example .kicker { color: var(--teal); }\n.example p { margin: 0; font-size: 18.5px; font-style: italic; color: var(--ink); }\n\n.why { padding: 16px 20px; border-radius: 14px; border: 1px dashed var(--teal-light); display: grid; gap: 4px; }\n.why .kicker { color: var(--teal); }\n.why p { margin: 0; font-size: 17px; color: var(--ink-2); }\n\n/* fórmula do rótulo */\n.formula { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n.formula div { padding: 14px 16px; border-radius: 12px; border: 2px solid var(--teal-light); display: grid; gap: 2px; min-width: 0; }\n.formula b { font-family: var(--title); font-weight: 600; font-size: 20px; color: var(--teal); }\n.formula span { font-size: 14px; color: var(--muted); }\n\n/* ciclo da dor */\n.loop { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }\n.loop div { position: relative; padding: 16px; border-radius: 14px; background: var(--bg); border: 1px solid var(--line); font-size: 17.5px; line-height: 1.35; font-weight: 600; min-width: 0; }\n.loop div::after { content: \"→\"; position: absolute; right: -15px; top: 50%; transform: translateY(-50%); width: 22px; height: 22px; border-radius: 50%; background: var(--teal); color: #fff; font-size: 12px; display: grid; place-items: center; z-index: 1; }\n.loop div:last-child::after { content: \"↺\"; }\n.grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.box { padding: 18px 20px; border-radius: 14px; background: var(--bg); border: 1px solid var(--line); display: grid; gap: 8px; align-content: start; min-width: 0; }\n.box h3 { margin: 0; font-family: var(--title); font-weight: 600; font-size: 19px; line-height: 1.2; color: var(--teal); }\n.box p { margin: 0; color: var(--ink-2); font-size: 16.5px; }\n.box q { color: var(--ink); font-weight: 600; quotes: \"“\" \"”\"; }\n\n/* mesinha de 3 pernas */\n.mesa { display: grid; gap: 0; margin-top: 4px; }\n.tampo { height: 20px; border-radius: 10px; background: linear-gradient(90deg, var(--teal-2), var(--teal), var(--teal-2)); box-shadow: 0 10px 30px rgba(36, 117, 127, 0.25); }\n.pernas { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }\n.perna { display: grid; grid-template-rows: auto 1fr; justify-items: center; min-width: 0; }\n.perna i { width: 10px; height: 40px; background: linear-gradient(var(--teal), var(--teal-light)); border-radius: 0 0 4px 4px; }\n.perna .box { width: 100%; background: var(--card); border: 2px solid var(--teal-light); }\n.perna .box b { font-family: var(--title); font-weight: 700; font-size: 30px; line-height: 1; color: var(--teal); }\n.perna .box h3 { color: var(--ink); }\n.perna .box p { color: var(--ink-2); font-size: 16.5px; }\n.perna .box .ok { font-family: var(--label); font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: var(--coral); font-size: 13px; }\n.cai { text-align: center; font-family: var(--title); font-weight: 600; font-size: 22px; margin: 16px 0 0; color: var(--ink); }\n\n.steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; counter-reset: s; }\n.steps > li { counter-increment: s; display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 14px; align-items: start; }\n.steps > li::before { content: counter(s); font-family: var(--title); font-weight: 700; font-size: 22px; line-height: 44px; height: 44px; color: #fff; text-align: center; background: var(--teal); border-radius: 12px; }\n.steps h3 { margin: 6px 0 2px; font-family: var(--title); font-weight: 600; font-size: 21px; line-height: 1.2; color: var(--ink); }\n.steps p { margin: 0; color: var(--ink-2); font-size: 17px; }\n.trailer { display: inline-flex; align-items: center; gap: 8px; font-size: 13.5px; font-weight: 700; color: var(--teal); background: var(--teal-wash); border-radius: 999px; padding: 4px 12px; margin-top: 8px; }\n.btn { display: inline-flex; align-items: center; gap: 10px; justify-self: start; text-decoration: none; font-family: \"Roboto\", var(--body); font-weight: 800; font-size: 16px; letter-spacing: 0.02em; text-transform: uppercase; color: #fff; background: var(--coral); padding: 14px 26px; border-radius: 999px; box-shadow: 0 10px 24px rgba(226, 61, 89, 0.28); transition: background 0.2s, transform 0.2s; }\n.btn:hover { background: var(--coral-dark); transform: translateY(-1px); }\n\n/* escada de preço */\n.ladder { display: grid; gap: 8px; }\n.step { display: grid; grid-template-columns: 140px 210px minmax(0, 1fr); gap: 16px; align-items: center; padding: 14px 18px; border-radius: 14px; background: var(--bg); border: 1px solid var(--line); }\n.step .price { font-family: var(--title); font-weight: 700; font-size: 28px; line-height: 1; color: var(--coral); font-variant-numeric: tabular-nums; }\n.step .when { font-family: var(--label); font-weight: 600; font-size: 12.5px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }\n.step .line { font-size: 17px; line-height: 1.4; }\n.step:nth-child(1) { margin-right: 54px; }\n.step:nth-child(2) { margin-right: 36px; }\n.step:nth-child(3) { margin-right: 18px; }\n.step.bonus { background: var(--teal-wash); border-color: var(--teal-light); }\n.step.bonus .price { color: var(--teal); }\n.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 14px; }\ntable { width: 100%; border-collapse: collapse; font-size: 14.5px; font-variant-numeric: tabular-nums; min-width: 560px; }\nth, td { text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }\nth { font-family: var(--label); font-weight: 600; color: var(--muted); font-size: 12.5px; text-transform: uppercase; letter-spacing: 0.08em; background: var(--bg); }\ntr:last-child td { border-bottom: 0; }\ntd.save { color: var(--teal); font-weight: 700; }\n.note { font-size: 13.5px; color: var(--muted); margin: 0; }\n\n/* objeções */\n.virada { padding: 18px 22px; border-radius: 16px; border: 1px dashed var(--teal-light); display: grid; gap: 10px; }\n.virada .kicker { color: var(--teal); }\n.virada ol { margin: 0; padding-left: 22px; display: grid; gap: 8px; font-size: 17px; color: var(--ink-2); }\n.virada ol li::marker { color: var(--teal); font-weight: 700; }\n.virada b { color: var(--ink); }\n.virada .slot, .obj .slot { border-bottom: 2px dashed var(--coral); }\n.obj .links { display: flex; flex-wrap: wrap; gap: 8px; }\n.cofre-link { justify-self: start; font-family: var(--label); font-weight: 600; font-size: 12.5px; letter-spacing: 0.08em; text-transform: uppercase; text-decoration: none; color: var(--teal); padding: 6px 12px; border-radius: 999px; border: 1px solid var(--teal-light); }\n.cofre-link:hover { background: var(--teal); color: #fff; border-color: var(--teal); }\n.jump { display: flex; flex-wrap: wrap; gap: 8px; }\n.jump a { font-size: 14px; font-weight: 600; text-decoration: none; padding: 6px 14px; border-radius: 999px; background: var(--bg); border: 1px solid var(--line); color: var(--ink-2); }\n.jump a:hover { border-color: var(--coral); color: var(--coral); }\n.objs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }\n.obj { padding: 20px 22px; border-radius: 16px; background: var(--bg); border: 1px solid var(--line); display: grid; gap: 10px; align-content: start; min-width: 0; scroll-margin-top: 20px; }\n.obj:target { border-color: var(--coral); background: var(--coral-wash); }\n.obj header { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; align-items: center; }\n.obj header b { font-family: var(--title); font-weight: 700; font-size: 17px; width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: var(--coral); }\n.obj h3 { margin: 0; font-family: var(--title); font-weight: 600; font-size: 20px; line-height: 1.2; color: var(--ink); }\n.obj .resp { margin: 0; font-size: 17.5px; line-height: 1.5; color: var(--ink); }\n.obj .resp em { font-style: normal; font-weight: 700; color: var(--teal); }\n.obj ol { margin: 0; padding-left: 22px; display: grid; gap: 6px; font-size: 17px; }\n.obj ol li::marker { color: var(--coral); font-weight: 700; }\n.obj .tip { font-size: 14.5px; color: var(--muted); border-top: 1px solid var(--line-2); padding-top: 10px; margin: 0; }\n.obj.wide { grid-column: 1 / -1; }\n\n/* depois do sim: faixa teal, como os bônus do site */\n.stage.teal { background: var(--teal); color: #fff; border-color: var(--teal); }\n.stage.teal h2 { color: #fff; }\n.stage.teal h2 .t { color: var(--teal-light); }\n.stage.teal .tag { background: #fff; color: var(--teal); }\n.stage.teal .say { background: #fff; color: var(--ink); box-shadow: none; }\n.stage.teal .say::before { color: var(--coral); }\n.stage.teal .say .slot { color: var(--coral); border-bottom-color: var(--coral); }\n.stage.teal .do li { color: rgba(255, 255, 255, 0.9); }\n.stage.teal .do li::before { background: #fff; color: var(--teal); }\n.after-yes { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; counter-reset: a; }\n.after-yes div { counter-increment: a; padding: 16px 18px; border-radius: 14px; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.22); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.after-yes div::before { content: counter(a); font-family: var(--title); font-weight: 700; font-size: 26px; line-height: 1; color: var(--teal-light); }\n.after-yes b { font-family: var(--title); font-weight: 600; font-size: 18px; line-height: 1.2; }\n.after-yes span { font-size: 15.5px; color: rgba(255, 255, 255, 0.85); line-height: 1.42; }\n\nfooter { margin-top: 12px; background: #1c1c1c; color: rgba(255, 255, 255, 0.7); }\nfooter .wrap { padding-block: 22px calc(30px + env(safe-area-inset-bottom, 0px)); font-size: 13px; display: flex; flex-wrap: wrap; gap: 8px 24px; justify-content: space-between; align-items: center; }\nfooter img { width: 92px; height: auto; display: block; }\n\n@media (max-width: 1100px) {\n  .closer { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n  .step { grid-template-columns: 130px minmax(0, 1fr); }\n  .step .line { grid-column: 1 / -1; }\n  .after-yes { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .loop { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .loop div::after { display: none; }\n}\n@media (max-width: 900px) {\n  .hero { background-position: 70% center; }\n  .hero::before { background: linear-gradient(180deg, rgba(20, 20, 20, 0.86), rgba(20, 20, 20, 0.92)); }\n  .layout { grid-template-columns: minmax(0, 1fr); gap: 16px; padding-top: 16px; }\n  .nav { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; display: flex; gap: 6px; overflow-x: auto; padding: 10px max(16px, env(safe-area-inset-left, 0px)); border-radius: 0; margin-inline: calc(-1 * max(16px, env(safe-area-inset-left, 0px))); border-width: 0 0 1px; box-shadow: none; }\n  .nav .label, .nav .rule { display: none; }\n  .nav a { flex: none; grid-template-columns: auto auto; padding: 6px 12px; font-size: 14.5px; border: 1px solid var(--line); border-radius: 999px; }\n  .nav a b { font-size: 15px; }\n  .stage { padding: 24px 20px 26px; }\n}\n@media (max-width: 720px) {\n  body { font-size: 17px; }\n  .hero .wrap { padding-block: 28px 104px; }\n  .hero .logo { width: 132px; }\n  .closer { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: -70px; }\n  .say { font-size: 19px; padding: 14px 18px 16px; }\n  .say.small { font-size: 17.5px; }\n  .formula, .grid2, .pernas, .objs, .after-yes, .loop { grid-template-columns: minmax(0, 1fr); }\n  .perna i, .tampo { display: none; }\n  .step { grid-template-columns: minmax(0, 1fr); gap: 6px; }\n  .step:nth-child(n) { margin-right: 0; }\n}\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } .closer a, .btn { transition: none; } }\n</style>\n</head>\n<body>\n<header class=\"hero\">\n  <div class=\"wrap\">\n    <img class=\"logo\" src=\"/marca/a5e-logo.webp\" alt=\"Anfitrião 5 Estrelas\" width=\"480\" height=\"183\">\n    <div class=\"pills\">\n      <span class=\"pill\">Roteiro novo · time comercial</span>\n      <span class=\"pill\">Call de 30 min no Teams</span>\n      <span class=\"pill coral\">Etapas do CLOSER</span>\n    </div>\n    <h1>O roteiro <span class=\"c\">da call</span></h1>\n    <p class=\"lede\">Primeiro a gente pergunta e escuta. <strong>Só mostra a comunidade depois que o lead disse onde está, onde quer chegar e o que está no caminho.</strong></p>\n    <div class=\"postura\">\n      <b>Postura</b>\n      <span>Ela clicou, se cadastrou e agendou: veio porque quis. Você está aqui pra ajudar a resolver o problema dela, e quem decide é ela. Sem pressa de fechar e sem técnica agressiva: quem sente desespero pela comissão desconfia.</span>\n    </div>\n  </div>\n</header>\n\n<div class=\"wrap\">\n  <nav class=\"closer\" aria-label=\"As 8 etapas\">\n    <a href=\"#e1\"><b>1</b><span>Clarificar</span></a>\n    <a href=\"#e2\"><b>2</b><span>Rotular</span></a>\n    <a href=\"#e3\"><b>3</b><span>Ciclo da dor</span></a>\n    <a href=\"#e4\"><b>4</b><span>Transição</span></a>\n    <a href=\"#e5\"><b>5</b><span>Vender a viagem</span></a>\n    <a href=\"#e6\"><b>6</b><span>Fechamento</span></a>\n    <a href=\"#e7\"><b>7</b><span>Objeções</span></a>\n    <a href=\"#e8\"><b>8</b><span>Depois do sim</span></a>\n  </nav>\n</div>\n\n<div class=\"wrap layout\">\n  <nav class=\"nav\" aria-label=\"Etapas da call\">\n    <span class=\"label\">Etapas</span>\n    <a href=\"#e1\"><b>1</b>Clarificar</a>\n    <a href=\"#e2\"><b>2</b>Rotular</a>\n    <a href=\"#e3\"><b>3</b>Ciclo da dor</a>\n    <a href=\"#e4\"><b>4</b>Transição</a>\n    <a href=\"#e5\"><b>5</b>Vender a viagem</a>\n    <a href=\"#e6\"><b>6</b>Fechamento</a>\n    <a href=\"#e7\"><b>7</b>Objeções</a>\n    <a href=\"#e8\"><b>8</b>Depois do sim</a>\n    <div class=\"rule\">Pergunta e escuta <strong>antes</strong> de mostrar. A comunidade só entra na etapa 5. Quanto mais fiel ao roteiro, maior o fechamento.</div>\n  </nav>\n\n  <main>\n    <!-- 1 -->\n    <section class=\"stage\" id=\"e1\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 1 · Clarificar</span><h2>Por que a pessoa <span class=\"t\">está aqui</span></h2></div>\n      <div class=\"says\">\n        <p class=\"say\">O que te fez entrar na lista de espera e agendar essa chamada?</p>\n        <p class=\"say small\">Me conta mais.</p>\n        <p class=\"say small\">E que mais?</p>\n      </div>\n      <ul class=\"do\">\n        <li>Depois da pergunta, só escuta. Quando ela parar, “me conta mais” e “e que mais?”. Quanto mais ela fala, mais problema aparece: temporada fraca, mensagem que não vira reserva, imóvel que não roda.</li>\n        <li>Chega com a ficha do Téo e não repete as perguntas de cadastro.</li>\n      </ul>\n      <div class=\"dontbox\">\n        <span class=\"kicker\">Nessa etapa, não</span>\n        <ul class=\"dont\">\n          <li>Nada de comunidade, de Rômulo ou de preço.</li>\n          <li>A pergunta “você conhece o Rômulo?” saiu do roteiro.</li>\n        </ul>\n      </div>\n    </section>\n\n    <!-- 2 -->\n    <section class=\"stage\" id=\"e2\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 2 · Rotular</span><h2>Devolver o problema <span class=\"t\">nas palavras dela</span></h2></div>\n      <div class=\"says\">\n        <p class=\"say\">Deixa eu ver se entendi: hoje você <span class=\"slot\">[onde está]</span>, quer chegar em <span class=\"slot\">[meta]</span>, e o que está no caminho é <span class=\"slot\">[problema]</span>. É isso?</p>\n      </div>\n      <div class=\"formula\" aria-hidden=\"true\">\n        <div><b>Onde está</b><span>a situação de hoje</span></div>\n        <div><b>Meta</b><span>onde quer chegar</span></div>\n        <div><b>Problema</b><span>o que está no caminho</span></div>\n      </div>\n      <div class=\"example\">\n        <span class=\"kicker\">Exemplo real, call de 03/11</span>\n        <p>“Hoje vocês estão construindo 12 lofts em Foz, querem que eles rodem sozinhos pra vocês poderem viajar, e o que está no caminho é que você nunca mexeu com Airbnb e tem medo de errar no preço. É isso?”</p>\n      </div>\n      <div class=\"why\">\n        <span class=\"kicker\">Por que funciona</span>\n        <p>Quando você diz o problema dela melhor do que ela mesma conseguiu dizer, ela sente que foi entendida. É o médico que aponta: “a dor é aqui, no joelho direito, né?”. Daí pra frente ela confia na solução.</p>\n      </div>\n      <ul class=\"do\"><li>Se ela corrigir, rotula de novo até ouvir “é isso”.</li></ul>\n    </section>\n\n    <!-- 3 -->\n    <section class=\"stage\" id=\"e3\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 3 · Visão geral</span><h2>O ciclo <span class=\"t\">da dor</span></h2></div>\n      <p class=\"intro\">Pergunte em sequência e repita até ela dizer que é só isso.</p>\n      <div class=\"loop\">\n        <div>O que você já tentou até agora pra resolver isso?</div>\n        <div>E como foi?</div>\n        <div>O que você gostou? E o que não gostou?</div>\n        <div>Tentou mais alguma coisa?</div>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"box\"><h3>O que ela gostou vira ponte</h3><p><q>Se você gostou disso, vai adorar…</q> Do que ela não gostou, você não fala nada parecido: se reclamou de curso com aula demais, não fale das horas de aula.</p></div>\n        <div class=\"box\"><h3>Quem decide e como quer</h3><p><q>Alguém decide isso junto com você?</q></p><p><q>Você quer aprender a fazer ou prefere que alguém faça por você?</q></p></div>\n        <div class=\"box\"><h3>Munição pro preço</h3><p><q>Qual é a diária média hoje? Quantas noites por mês fica ocupado?</q> Se o imóvel ainda não roda: <q>Qual diária você espera cobrar?</q></p><p>E a situação: imóvel pronto, em obra, alugado no fixo, quantos imóveis. Esses números vão para a Calculadora de Ganhos na etapa 5.</p></div>\n        <div class=\"box\"><h3>Ache a perna bamba</h3><p><q>Chega mensagem de hóspede e não fecha, ou nem chega?</q></p><p><q>Você muda o preço na mão, no automático ou deixa fixo?</q></p><p>Na hora de vender a viagem, demore mais na perna fraca.</p></div>\n      </div>\n      <div class=\"why\">\n        <span class=\"kicker\">Objeção no fim é pergunta que faltou no começo</span>\n        <p>O “vou pensar” do final quase sempre é algo que não foi perguntado aqui. Capriche no diagnóstico e o fechamento fica leve.</p>\n      </div>\n    </section>\n\n    <!-- 4 -->\n    <section class=\"stage\" id=\"e4\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 4 · Transição</span><h2>Pedir licença <span class=\"t\">e combinar</span></h2></div>\n      <div class=\"says\">\n        <p class=\"say\">Acho que você vai gostar do que a gente tem. Posso te mostrar?</p>\n        <p class=\"say small\">Antes, um combinado. No final você pode ter dois sentimentos. Um é: “faz muito sentido pro meu momento, resolve o meu problema”. Aí a gente já vê como você começa. O outro é: “não era isso que eu precisava agora”. E tudo bem: pode ser 100% sincero comigo, que eu até te indico outro caminho. Combinado?</p>\n      </div>\n      <ul class=\"do\">\n        <li>Pedir licença deixa a pessoa pronta pra ouvir e menos impaciente com a apresentação.</li>\n        <li>O combinado tira a pressão (ela sabe que pode dizer não) e já deixa acertado que no fim vem uma resposta, sim ou não, em vez de “vou pensar”.</li>\n        <li>Com lead que só responde “sim” e “não”, o combinado faz a pessoa falar mais.</li>\n        <li>Diga com as suas palavras e espere o “combinado”. Lido em tom de técnica, soa como truque.</li>\n      </ul>\n    </section>\n\n    <!-- 5 -->\n    <section class=\"stage\" id=\"e5\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 5 · Vender a viagem</span><h2>Resultado, <span class=\"t\">não módulo</span></h2></div>\n      <p class=\"intro\">Fale do resultado: calendário cheio, 5 estrelas, o Pix caindo, viajar enquanto o imóvel roda. Sem tour pelos módulos. E chame de <strong>comunidade</strong>, não de curso: as aulas gravadas, o grupo e os encontros fazem parte dela.</p>\n      <ol class=\"steps\">\n        <li>\n          <div>\n            <h3>Trailer do Anfitrião 5 Estrelas</h3>\n            <p>Compartilhe a tela com o som do computador, antes dos pilares. Logo depois, uma frase curta sobre o Rômulo. A maioria já conhece a história: conte resumido e não pergunte se conhece.</p>\n            <span class=\"trailer\">▶ 3min46</span>\n          </div>\n        </li>\n      </ol>\n      <div class=\"says\"><p class=\"say small\">O Rômulo começou em 2016 alugando no Airbnb um quartinho do apartamento onde ele morava, pra ajudar a pagar o aluguel. Hoje ele administra mais de 70 imóveis.</p></div>\n      <ol class=\"steps\" start=\"2\" style=\"counter-reset: s 1\">\n        <li><div><h3>A mesinha de 3 pernas</h3><p>Com um “Faz sentido?” depois de cada perna. Explique com as suas palavras, sem passar vídeo.</p></div></li>\n      </ol>\n      <div class=\"says\"><p class=\"say small\">Pra um imóvel de temporada dar certo, ele é como uma mesinha de 3 pernas.</p></div>\n      <div class=\"mesa\" aria-label=\"A mesinha de 3 pernas\">\n        <div class=\"tampo\"></div>\n        <div class=\"pernas\">\n          <div class=\"perna\"><i></i><div class=\"box\"><b>1</b><h3>Anúncio</h3><p>Um anúncio que chama a atenção e converte interessados em hóspedes: fotos, título e descrição do jeito que a gente ensina.</p><span class=\"ok\">Faz sentido?</span></div></div>\n          <div class=\"perna\"><i></i><div class=\"box\"><b>2</b><h3>Algoritmo</h3><p>A configuração perfeita pra você virar um queridinho do algoritmo e ser visto por muito mais gente.</p><span class=\"ok\">Faz sentido?</span></div></div>\n          <div class=\"perna\"><i></i><div class=\"box\"><b>3</b><h3>Experiência</h3><p>Operação e atendimento bons pra receber 5 estrelas, e aí o algoritmo te empurra ainda mais: o ciclo virtuoso.</p><span class=\"ok\">Faz sentido?</span></div></div>\n        </div>\n        <p class=\"cai\">“Com as três pernas em pé, não tem como dar errado. <span class=\"c\">Se uma falhar, a mesa cai.</span>”</p>\n      </div>\n      <ol class=\"steps\" start=\"3\" style=\"counter-reset: s 2\">\n        <li><div><h3>Comunidade e lives</h3><p>Logo depois da mesinha. É o que as pessoas mais querem: não fazer nada sozinhas.</p></div></li>\n      </ol>\n      <div class=\"says\"><p class=\"say small\">E você não faz isso sozinho. Empreender é solitário, e na comunidade você está com gente que trabalha com a mesma coisa o tempo todo e quer melhorar. Tem o grupo no WhatsApp com proprietários do Brasil inteiro e as lives com o Rômulo pra tirar dúvida. Só de estar lá, vendo as perguntas dos outros, você já aprende.</p></div>\n      <ol class=\"steps\" start=\"4\" style=\"counter-reset: s 3\">\n        <li><div><h3>Calculadora de Ganhos</h3><p>Com a diária e as noites que ela te deu na etapa 3, mostre na tela quanto 10% a mais na diária e algumas noites a mais rendem por mês e por ano. Ver o número pesa mais que ouvir.</p></div></li>\n      </ol>\n      <a class=\"btn\" href=\"/calculadora\" target=\"_blank\" rel=\"noopener\">Abrir a Calculadora de Ganhos ↗</a>\n      <ul class=\"do\">\n        <li>Uma imagem do Rômulo ajuda, mas não é obrigatória.</li>\n        <li>Os casos de alunos ficam para as objeções: use o mais parecido com o lead, no <a href=\"/cofre\" target=\"_blank\" rel=\"noopener\">Cofre de Cases</a>.</li>\n      </ul>\n    </section>\n\n    <!-- 6 -->\n    <section class=\"stage\" id=\"e6\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 6 · Fechamento</span><h2>Primeiro o resumo, <span class=\"t\">depois o preço</span></h2></div>\n      <div class=\"says\">\n        <p class=\"say\">Então, resumindo: você entra na comunidade com as aulas gravadas, o grupo de WhatsApp com o Rômulo dentro e as lives mensais pra tirar dúvida.</p>\n        <p class=\"say small\">Lembra que você me disse que <span class=\"slot\">[o problema dela]</span>? É exatamente isso que a gente resolve com <span class=\"slot\">[a perna ou a comunidade]</span>.</p>\n        <p class=\"say small\">Faz sentido pra você? Ficou alguma dúvida?</p>\n        <p class=\"say small\">E lembra do nosso combinado? Qual dos dois sentimentos ficou?</p>\n        <p class=\"say\">O investimento é R$ 2.997, ou 12x de R$ 299,70. E você tem 14 dias de garantia. A lei dá 7, a gente dá 14: é o dobro. Se não for o que eu te disse, devolvemos 100%, sem precisar explicar nada. Bora começar hoje?</p>\n      </div>\n      <ul class=\"do\">\n        <li>Antes do preço, faça a pessoa dizer que entendeu. Se ficou dúvida, volte e explique: preço só depois de clareza.</li>\n        <li>O preço vem depois do “faz sentido”, o primeiro dos dois sentimentos. Se for o segundo, pergunte o que faltou: é uma objeção (etapa 7).</li>\n        <li>Volte à dor dela mais de uma vez, com as palavras dela.</li>\n        <li>Qualquer resposta que não seja “sim” vai para as objeções (etapa 7).</li>\n      </ul>\n\n      <span class=\"kicker\">Escada de preço · cada degrau vem com aprovação e prazo</span>\n      <div class=\"ladder\" aria-label=\"Escada de preço\">\n        <div class=\"step\"><span class=\"price\">R$ 2.997</span><span class=\"when\">Sempre o primeiro</span><span class=\"line\">O fechamento acima.</span></div>\n        <div class=\"step\"><span class=\"price\">R$ 2.797</span><span class=\"when\">Objeção de preço (cupom)</span><span class=\"line\">“Tenho um cupom que deixa em R$ 2.797. Como o cupom não é perpétuo, ele vale até amanhã às 13h.”</span></div>\n        <div class=\"step\"><span class=\"price\">R$ 2.497</span><span class=\"when\">Só com uma trava concreta</span><span class=\"line\">“Conversei com a minha equipe e consegui aprovar R$ 2.497, válido até amanhã às 13h.”</span></div>\n        <div class=\"step bonus\"><span class=\"price\">Bônus</span><span class=\"when\">Pediu mais desconto</span><span class=\"line\">Não baixa mais: oferece o curso de Booking de bônus.</span></div>\n      </div>\n\n      <span class=\"kicker\">Reclamou dos juros? Menos parcelas</span>\n      <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>Preço à vista</th><th>12x (total)</th><th>6x (total)</th><th>4x (total)</th><th>6x economiza</th></tr></thead>\n          <tbody>\n            <tr><td>R$ 2.997 (tabela)</td><td>R$ 299,70 (R$ 3.596)</td><td>R$ 551,83 (R$ 3.311)</td><td>R$ 804,79 (R$ 3.219)</td><td class=\"save\">R$ 285</td></tr>\n            <tr><td>R$ 2.797 (cupom)</td><td>R$ 279,70 (R$ 3.356)</td><td>R$ 515,00 (R$ 3.090)</td><td>R$ 751,08 (R$ 3.004)</td><td class=\"save\">R$ 266</td></tr>\n            <tr><td>R$ 2.497 (aprovação)</td><td>R$ 249,70 (R$ 2.996)</td><td>R$ 459,76 (R$ 2.759)</td><td>R$ 670,52 (R$ 2.682)</td><td class=\"save\">R$ 237</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <p class=\"note\">Taxa da Eduzz de 2,92% ao mês. Confira no checkout antes de usar.</p>\n    </section>\n\n    <!-- 7 -->\n    <section class=\"stage\" id=\"e7\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 7 · Objeções</span><h2>As 11 que <span class=\"t\">mais aparecem</span></h2></div>\n      <p class=\"intro\">As 10 primeiras estão na ordem do que mais aparece nas conversas. A 11ª entrou depois e é a 5ª mais comum. Cada uma tem a fala, o jeito de virar e o botão do Cofre de Cases já filtrado com as histórias pra essa objeção.</p>\n      <a class=\"btn\" href=\"/cofre\" target=\"_blank\" rel=\"noopener\">Abrir o Cofre de Cases ↗</a>\n\n      <div class=\"virada\">\n        <span class=\"kicker\">Antes de responder qualquer objeção</span>\n        <ol>\n          <li><b>Acolha.</b> “Faz sentido.” “Sem problema.” Não discuta nem rebata de primeira.</li>\n          <li><b>Descubra a de verdade.</b> “O que está te pegando?” A objeção que a pessoa fala nem sempre é a que trava. Com mais intimidade, em voz mais baixa: “O que você tem medo que aconteça?”</li>\n          <li><b>Isole.</b> “Tirando isso, tem mais alguma coisa que te impede de começar hoje?” Assim você responde uma vez só, e a certa.</li>\n          <li><b>Responda com lógica e prova.</b> A fala da objeção e o caso mais parecido com o lead no Cofre. Um caso só, bem contado.</li>\n          <li><b>Volte à dor e peça de novo.</b> “Lembra que você me disse que <span class=\"slot\">[problema dela]</span>? Faz sentido? Bora começar?”</li>\n          <li><b>Não fechou? Data e hora.</b> Nunca aceite “vou pensar” sem pergunta e sem data: “Amanhã às 11h eu te chamo pra você me dar a resposta, pode ser?”</li>\n        </ol>\n        <p class=\"note\">Sem promessa de ganho: mostre o que outro aluno fez. A garantia de 14 dias é pra quem está com receio; use sem medo, quase ninguém pede o dinheiro de volta.</p>\n      </div>\n\n      <nav class=\"jump\" aria-label=\"Ir para a objeção\">\n        <a href=\"#o1\">Preço</a><a href=\"#o2\">Momento</a><a href=\"#o3\">Vou pensar</a><a href=\"#o4\">YouTube</a><a href=\"#o5\">Cônjuge ou sócio</a><a href=\"#o6\">Serve pro meu caso?</a><a href=\"#o7\">Juros</a><a href=\"#o8\">Façam por mim</a><a href=\"#o9\">Confiança</a><a href=\"#o10\">Já fiz curso</a><a href=\"#o11\">Não tenho tempo</a>\n      </nav>\n      <div class=\"objs\">\n        <article class=\"obj\" id=\"o1\">\n          <header><b>1</b><h3>Preço</h3></header>\n          <p class=\"resp\">Primeiro descubra qual é o “caro”: “Tirando o preço, faz sentido pra você? O que pesa: o valor total, a parcela no mês ou a dúvida se volta pra você?”</p>\n          <p class=\"resp\"><em>Se é o retorno:</em> “12x de R$ 299,70 é menos que uma diária sua de R$ <span class=\"slot\">[diária dela]</span> por mês. Uma diária a mais por mês e já se pagou.” Com a Calculadora aberta, mostre em quantos dias de ganho extra o investimento volta.</p>\n          <p class=\"resp\"><em>Se duvida que funciona pra ela:</em> o Danilo era barbeiro havia 18 anos, fez o curso e em 2 meses fez uns R$ 18 mil. “Pra ganhar R$ 1.000 eu tinha que cortar 20 cabelos. Hoje a cobertura é R$ 1.000 a diária.”</p>\n          <p class=\"resp\"><em>Se é a parcela:</em> 12x, boleto parcelado ou dois cartões. Aí entra o cupom da escada (R$ 2.797).</p>\n          <p class=\"resp\">“E é uma vez só: o que você aprende fica com você em todo imóvel que tiver.”</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=preco\" target=\"_blank\" rel=\"noopener\">Cofre: casos pra preço ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o2\">\n          <header><b>2</b><h3>Momento (obra, bebê, viagem, mês que vem)</h3></header>\n          <p class=\"resp\">“Quanto isso é importante pra você? Lá no começo você me disse que <span class=\"slot\">[problema dela]</span>. Isso continua acontecendo enquanto a gente espera.”</p>\n          <p class=\"resp\">“O que vai estar diferente no mês que vem?” A resposta mostra se é momento mesmo ou outra objeção.</p>\n          <p class=\"resp\"><em>Obra:</em> “A obra é o melhor momento: você estuda agora e já abre certo, com mobília, fotos e preço pensados pra temporada, sem refazer depois.”</p>\n          <p class=\"resp\"><em>Bebê, viagem, correria:</em> “As aulas ficam gravadas e o grupo fica no seu celular. Você começa no seu ritmo e não perde nada.”</p>\n          <p class=\"tip\">Se não fechar, marque a retomada com data e hora, no sistema.</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=momento-obra\" target=\"_blank\" rel=\"noopener\">Cofre: casos de obra e momento ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o3\">\n          <header><b>3</b><h3>Vou pensar</h3></header>\n          <p class=\"resp\">“Sem problema, a gente não quer que você feche com pressa. Mas me ajuda a te ajudar: o que está te pegando? É o dinheiro, o momento, alguém de casa ou alguma dúvida sobre a comunidade?” A resposta leva pra objeção certa.</p>\n          <p class=\"resp\"><em>Se não aparece nada concreto,</em> uma pergunta por vez: “Você acha que com a comunidade chega mais longe do que sem ela?” “E mais rápido com quem já passou por isso te mostrando o caminho do que sozinha?” “Tem como pagar?” Três sins: “Então você já decidiu com a cabeça. O que sobra é o frio na barriga, e isso é normal.”</p>\n          <p class=\"resp\">“O Rômulo levou quase 10 anos batendo cabeça pra chegar nesse método: diária errada, temporada perdida. Você pega pronto, sem pagar pelos erros.”</p>\n          <p class=\"tip\">Em voz mais baixa: “O que você tem medo que aconteça?” Se mesmo assim quiser pensar: “Fechado. Que horas amanhã eu te chamo pra você me dar a resposta? Lembra do combinado: sim ou não, as duas estão ótimas.”</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=medo-de-errar\" target=\"_blank\" rel=\"noopener\">Cofre: medo de errar ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o4\">\n          <header><b>4</b><h3>YouTube ou lives grátis</h3></header>\n          <p class=\"resp\">“O que você faz hoje te dá o resultado que você tem hoje. Há quanto tempo você assiste os vídeos? E o que mudou no seu calendário nesse tempo?”</p>\n          <p class=\"resp\">“No YouTube o Rômulo mostra o quê fazer, em peças soltas, no dia que sai. Na comunidade é o como, tintim por tintim, na ordem certa, e você pergunta no grupo quando travar.”</p>\n          <p class=\"resp\"><em>Prova:</em> a Nat maratonou os vídeos do Rômulo e levou a casinha da garagem de R$ 33 mil pra R$ 70 mil por ano. Pra chegar nos 17 imóveis, entrou na comunidade: “foi o divisor de águas”.</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=sozinho-youtube\" target=\"_blank\" rel=\"noopener\">Cofre: quem começou pelos vídeos ↗</a>\n        </article>\n        <article class=\"obj wide\" id=\"o5\">\n          <header><b>5</b><h3>Cônjuge, sócio ou família</h3></header>\n          <p class=\"resp\"><em>Melhor ainda:</em> chamar o cônjuge para a call já na marcação. Se não veio: “Ele está aí perto? Chama ele, que eu explico em 5 minutos.” Se não dá: “O que você acha que ele vai te perguntar? Às vezes eu já te respondo agora.” Depois, as seis falas, nesta ordem:</p>\n          <ol>\n            <li>“E se ele não deixar?”</li>\n            <li>“Do que ele seria contra?” (responda o motivo, não a pessoa)</li>\n            <li>“Ele sabe que você está tentando resolver isso? Ele aprova ficar como está? Então por que seria contra resolver?”</li>\n            <li>“Acho que você está pedindo permissão quando precisa de apoio.”</li>\n            <li>“Daqui a 5 anos, se não fizer, quem você vai culpar?”</li>\n            <li>“Entra hoje e mostra pra ele lá dentro. Se ele não topar, você tem 14 dias e recebe tudo de volta.”</li>\n          </ol>\n          <p class=\"tip\">Vale igual pra mãe, pai e sócio.</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=conjuge-socio\" target=\"_blank\" rel=\"noopener\">Cofre: casais e sócios ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o6\">\n          <header><b>6</b><h3>Serve pro meu caso?</h3></header>\n          <p class=\"resp\"><em>Diagnóstico:</em> de 1 a 5 imóveis, Anfitrião 5 Estrelas. Com mais imóveis ou gestão para terceiros, Gigantes. Uma recomendação só.</p>\n          <p class=\"resp\"><em>Imóvel longe:</em> “Na comunidade o Rômulo mostra um imóvel em Balneário Camboriú, a 600 km da casa dele, rodando sem ele lá.”</p>\n          <p class=\"resp\"><em>Imóvel simples:</em> “Hóspede valoriza mais funcionalidade e limpeza do que luxo.”</p>\n          <p class=\"resp\"><em>Cidade pequena:</em> a Cidinha, de Rifaina (SP), ajustou o preço numa mentoria e hoje tem todos os fins de semana alugados.</p>\n          <p class=\"resp\"><em>Ainda sem imóvel:</em> “É o melhor jeito de começar: você escolhe e monta o imóvel já pensando em temporada.”</p>\n          <p class=\"tip\">Conte um caso só, o mais parecido com o lead.</p>\n          <div class=\"links\"><a class=\"cofre-link\" href=\"/cofre?objecoes=imovel-longe\" target=\"_blank\" rel=\"noopener\">Imóvel longe ↗</a><a class=\"cofre-link\" href=\"/cofre?objecoes=imovel-simples\" target=\"_blank\" rel=\"noopener\">Imóvel simples ↗</a><a class=\"cofre-link\" href=\"/cofre?objecoes=sem-imovel\" target=\"_blank\" rel=\"noopener\">Sem imóvel ↗</a></div>\n        </article>\n        <article class=\"obj\" id=\"o7\">\n          <header><b>7</b><h3>Juros</h3></header>\n          <p class=\"resp\">“O juros não é nosso, é da Eduzz. Mas dá pra pagar bem menos: em 6x fica R$ 551,83 por mês, uns R$ 285 a menos que no 12x. E no Pix à vista não tem juros.”</p>\n          <p class=\"resp\">Quase sempre o problema não é o juros, é a parcela caber no mês. Ache o número de parcelas que cabe: 4x, 6x ou 12x.</p>\n          <p class=\"tip\">Valores de 12x, 6x e 4x na tabela da etapa 6.</p>\n        </article>\n        <article class=\"obj\" id=\"o8\">\n          <header><b>8</b><h3>Quero que façam por mim</h3></header>\n          <p class=\"resp\">“Até pra isso você precisa entender o mínimo, pra saber o que cobrar. Quem contrata sem entender não sabe se o gestor está fazendo bem: diária, fotos, avaliações. Com o básico você cobra com critério e não fica refém.”</p>\n          <p class=\"resp\">“E te garanto: só de estar no grupo, cercado de gente falando disso o tempo todo, com o Rômulo respondendo a turma e você, você já aprende. Seis meses lá e você começa a entender várias dinâmicas pra ter mais resultado.”</p>\n        </article>\n        <article class=\"obj\" id=\"o9\">\n          <header><b>9</b><h3>Confiança</h3></header>\n          <p class=\"resp\">“Faz sentido desconfiar, tem muito golpe por aí. O pagamento é pela Eduzz, uma das maiores plataformas de pagamento de cursos do Brasil, num link seguro no seu nome. Você tem 14 dias de garantia com 100% de volta.”</p>\n          <p class=\"resp\"><em>Mostre, não só fale:</em> o grupo funcionando na tela, agora. E quem fala do Rômulo: o diretor comercial do Airbnb pra América do Sul foi no canal e disse que o Rômulo tem sucesso porque “as pessoas te ouvem”.</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=confianca\" target=\"_blank\" rel=\"noopener\">Cofre: elogios e autoridades ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o10\">\n          <header><b>10</b><h3>Já fiz curso e não serviu</h3></header>\n          <p class=\"resp\">Primeiro escute: “O que não funcionou nele?” Se foi aula demais ou falta de suporte, mostre o grupo e as lives. Do que ela não gostou, não fale nada parecido.</p>\n          <p class=\"resp\">“Pior que um investimento ruim é deixar ele te impedir de fazer um bom. Não deixa aquele curso te queimar duas vezes. O primeiro namoro da escola não deu certo e você não desistiu de namorar.”</p>\n          <p class=\"resp\">“Tem muito curso ruim e muito curso bom. Aqui quem entra quer continuar no grupo: a renovação é alta. E você ainda tem os 14 dias pra testar.”</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=ja-fiz-curso\" target=\"_blank\" rel=\"noopener\">Cofre: quem já tinha feito curso ↗</a>\n        </article>\n        <article class=\"obj\" id=\"o11\">\n          <header><b>11</b><h3>Não tenho tempo</h3></header>\n          <p class=\"resp\">“Hoje, quanto tempo por semana você gasta com o imóvel? Respondendo hóspede, resolvendo limpeza, mexendo em preço? Normalmente a falta de tempo vem justamente de fazer tudo sem processo. O que você aprende ali (mensagem automática, fechadura eletrônica, rotina de limpeza) é o que te devolve tempo.”</p>\n          <p class=\"resp\">“Você já está em grupo de WhatsApp de família e de amigos, né? Esse é um grupo que te ajuda a ganhar dinheiro com o imóvel. As aulas são gravadas: 10 minutinhos por dia já andam. E mesmo na semana mais corrida, só de estar no grupo, com o Rômulo respondendo a turma, você já aprende. Faz sentido?”</p>\n          <a class=\"cofre-link\" href=\"/cofre?objecoes=tempo\" target=\"_blank\" rel=\"noopener\">Cofre: casos de tempo ↗</a>\n        </article>\n      </div>\n    </section>\n\n    <!-- 8 -->\n    <section class=\"stage teal\" id=\"e8\">\n      <div class=\"stage-head\"><span class=\"tag\">Etapa 8 · Reforçar depois do sim</span><h2>O sim <span class=\"t\">não é o fim</span></h2></div>\n      <div class=\"says\">\n        <p class=\"say small\">Parabéns pela decisão! Me manda o comprovante que a minha equipe já libera os bônus.</p>\n        <p class=\"say small\">Decisão certa, porque <span class=\"slot\">[a meta dela, nas palavras dela]</span>. Você vai adorar a comunidade.</p>\n      </div>\n      <ul class=\"do\">\n        <li>Essa fala tira a ansiedade do “será que fiz besteira?”, que bate logo depois de pagar.</li>\n        <li>O link de pagamento vai durante a call.</li>\n        <li>Depois, o Téo recebe o aluno, repete a meta dele e passa os primeiros passos:</li>\n      </ul>\n      <div class=\"after-yes\">\n        <div><b>Entrar no grupo</b><span>E se apresentar.</span></div>\n        <div><b>Pesquisa de entrada</b><span>Diagnóstico refeito a cada 6 meses para medir as histórias de sucesso.</span></div>\n        <div><b>Módulo inicial</b><span>“Abre o seu anúncio do lado da aula e já vai mexendo. Só não muda mil coisas ao mesmo tempo: uma por vez, pra saber o que funcionou.”</span></div>\n        <div><b>Acompanhamento</b><span>O Téo acompanha o aluno depois da entrada.</span></div>\n      </div>\n    </section>\n  </main>\n</div>\n\n<footer>\n  <div class=\"wrap\">\n    <img src=\"/marca/a5e-logo.webp\" alt=\"Anfitrião 5 Estrelas\" width=\"480\" height=\"183\">\n    <span>Roteiro novo da call de vendas · ajustado na reunião do time de 12/11/2026. Vamos testar por um tempo: o que funcionar fica.</span>\n    <span>Uso interno do time comercial</span>\n  </div>\n</footer>\n\n<script>\n(function () {\n  var links = Array.prototype.slice.call(document.querySelectorAll('.nav a'));\n  var stages = links.map(function (a) { return document.querySelector(a.getAttribute('href')); });\n  function update() {\n    var y = window.scrollY + window.innerHeight * 0.3;\n    var idx = 0;\n    for (var i = 0; i < stages.length; i++) { if (stages[i] && stages[i].offsetTop <= y) idx = i; }\n    links.forEach(function (a, i) {\n      var on = i === idx;\n      a.classList.toggle('on', on);\n      if (on) a.setAttribute('aria-current', 'step'); else a.removeAttribute('aria-current');\n    });\n    var cur = links[idx];\n    var nav = cur && cur.parentElement;\n    if (nav && nav.scrollWidth > nav.clientWidth) {\n      var left = cur.offsetLeft - nav.clientWidth / 2 + cur.clientWidth / 2;\n      if (Math.abs(nav.scrollLeft - left) > 40) nav.scrollLeft = left;\n    }\n  }\n  window.addEventListener('scroll', update, { passive: true });\n  window.addEventListener('resize', update);\n  update();\n})();\n</script>\n</body>\n</html>\n";
export const CALCULADORA_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#0a4c52\">\n<title>Calculadora de Ganhos · Canal do Anfitrião</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Damion&family=Nunito:wght@600;700;800;900&family=Poppins:wght@500;600;700;800&display=swap\">\n<style>\n/* Calculadora de Ganhos no seu imóvel (Canal do Anfitrião). Feita pra tela\n   cheia na call e na visita técnica: à esquerda, a marca e o resultado\n   grande (o que o lead precisa ver); à direita, o card com os controles, em\n   contadores e botões de escolha (melhores no toque que slider). Tudo cabe\n   numa tela a partir de 1280×720. Cores do logo: coral → teal. */\n:root {\n  color-scheme: light;\n  --coral: #f2405a;\n  --coral-2: #e02e4a;\n  --coral-3: #b81f3a;\n  --coral-wash: #fff1f3;\n  --coral-line: #ffd3da;\n  --teal: #0a9497;\n  --teal-deep: #073f44;\n  --ink: #2c2230;\n  --ink-2: #6b5a63;\n  --muted: #9a8a92;\n  --line: #f1e6e9;\n  --title: \"Poppins\", \"Nunito\", system-ui, sans-serif;\n  --ui: \"Nunito\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n* { box-sizing: border-box; }\nhtml, body { height: 100%; }\nbody { margin: 0; font-family: var(--ui); color: #fff; -webkit-font-smoothing: antialiased; background: var(--teal-deep); overflow: hidden; }\nbutton, input { font: inherit; color: inherit; }\nbutton { cursor: pointer; }\n:focus-visible { outline: 3px solid #ffd3da; outline-offset: 3px; border-radius: 12px; }\n\n/* fundo: teal profundo com a estrela do logo em coral, grande e cortada */\n.fundo { position: fixed; inset: 0; z-index: 0; overflow: hidden; background:\n  radial-gradient(1200px 800px at 15% 110%, rgba(242, 64, 90, 0.35), transparent 60%),\n  radial-gradient(900px 700px at 0% 0%, rgba(10, 148, 151, 0.45), transparent 60%),\n  linear-gradient(135deg, #0b5d63 0%, #073f44 55%, #062f33 100%); }\n.fundo svg { position: absolute; }\n.fundo .estrela-a { width: 1100px; left: -260px; bottom: -330px; opacity: 0.22; }\n.fundo .estrela-b { width: 420px; left: 40%; top: -200px; opacity: 0.05; }\n\n.palco { position: relative; z-index: 1; height: 100vh; height: 100dvh; display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr); gap: clamp(20px, 3vw, 56px); align-items: center; padding: clamp(18px, 3.4vh, 40px) clamp(20px, 3.6vw, 64px) clamp(18px, 3.4vh, 40px) clamp(24px, 4.6vw, 88px); }\n\n/* lado da marca */\n.marca { display: grid; gap: clamp(8px, 1.8vh, 24px); align-content: center; min-width: 0; }\n.logo { width: clamp(96px, 15vh, 190px); height: auto; display: block; }\n.rotulo { font-weight: 800; letter-spacing: 0.32em; text-transform: uppercase; font-size: clamp(12px, 1.6vh, 16px); color: rgba(255, 255, 255, 0.78); }\n.marca h1 { margin: 0; font-family: var(--title); font-weight: 700; font-size: clamp(26px, 4.6vh, 54px); line-height: 1.06; letter-spacing: -0.015em; max-width: 14ch; }\n.marca h1 em { font-style: normal; color: #ffb3bf; }\n.resultado { display: grid; gap: 4px; margin-top: clamp(4px, 1vh, 12px); }\n.grande { font-family: var(--title); font-weight: 800; font-size: clamp(60px, 13.5vh, 168px); line-height: 0.92; letter-spacing: -0.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }\n.grande .mais { color: var(--coral); }\n.grande .rs { font-size: 0.42em; letter-spacing: -0.01em; vertical-align: 0.62em; margin-right: 0.08em; }\n.por { font-weight: 800; font-size: clamp(18px, 3vh, 32px); color: rgba(255, 255, 255, 0.85); line-height: 1.1; }\n.fatos { display: flex; flex-wrap: nowrap; gap: clamp(8px, 1.2vh, 12px); margin-top: clamp(6px, 1.6vh, 18px); }\n.fato { display: grid; padding: clamp(7px, 1.2vh, 14px) clamp(10px, 1vw, 18px); border-radius: 16px; background: rgba(255, 255, 255, 0.09); border: 1px solid rgba(255, 255, 255, 0.16); backdrop-filter: blur(6px); min-width: 0; }\n.fato b { font-family: var(--title); font-weight: 700; font-size: clamp(16px, 2.8vh, 30px); white-space: nowrap; line-height: 1.15; font-variant-numeric: tabular-nums; }\n.fato span { font-size: clamp(12px, 1.6vh, 15px); font-weight: 700; color: rgba(255, 255, 255, 0.72); }\n.fato.destaque { background: var(--coral); border-color: var(--coral); box-shadow: 0 10px 30px rgba(242, 64, 90, 0.35); }\n.fato.destaque span { color: rgba(255, 255, 255, 0.92); }\n.barras { display: grid; gap: 8px; max-width: 560px; margin-top: clamp(4px, 1.4vh, 16px); }\n.barra { display: grid; grid-template-columns: clamp(92px, 9vw, 130px) minmax(0, 1fr) auto; gap: 12px; align-items: center; font-size: clamp(12px, 1.7vh, 15px); font-weight: 800; color: rgba(255, 255, 255, 0.8); }\n.trilho { height: clamp(10px, 1.6vh, 16px); border-radius: 999px; background: rgba(255, 255, 255, 0.1); overflow: hidden; display: flex; }\n.trilho i { display: block; height: 100%; transition: width 0.6s cubic-bezier(.2, .8, .2, 1); }\n.trilho .base { background: rgba(255, 255, 255, 0.7); }\n.trilho .extra { background: var(--coral); }\n.barra b { font-family: var(--title); font-weight: 600; font-variant-numeric: tabular-nums; color: #fff; white-space: nowrap; }\n.teclas { display: flex; flex-wrap: wrap; gap: 6px 16px; align-items: center; font-size: clamp(12px, 1.6vh, 15px); font-weight: 800; color: rgba(255, 255, 255, 0.7); margin-top: clamp(2px, 1vh, 12px); }\nkbd { font-family: var(--ui); font-weight: 900; font-size: 0.86em; color: #fff; background: rgba(255, 255, 255, 0.12); border: 1px solid rgba(255, 255, 255, 0.35); border-bottom-width: 3px; border-radius: 7px; padding: 1px 7px; margin-right: 6px; }\n\n/* card dos controles, com moldura coral */\n.moldura { padding: clamp(8px, 1.2vh, 14px); border-radius: 34px; background: linear-gradient(160deg, var(--coral) 0%, var(--coral-2) 55%, var(--coral-3) 100%); box-shadow: 0 30px 80px rgba(0, 0, 0, 0.35); min-width: 0; }\n.card { background: #fff; color: var(--ink); border-radius: 26px; padding: clamp(18px, 3vh, 34px) clamp(18px, 2.4vw, 40px); display: grid; gap: clamp(12px, 2.2vh, 22px); }\n.linha-topo { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }\n.card h2 { margin: 0; font-family: var(--title); font-weight: 700; font-size: clamp(20px, 3.2vh, 32px); color: var(--ink); line-height: 1.1; }\n.card h2 small { display: block; font-family: var(--ui); font-weight: 700; font-size: clamp(12px, 1.6vh, 15px); color: var(--muted); }\n.segmento { display: inline-flex; padding: 4px; border-radius: 14px; background: var(--coral-wash); border: 1px solid var(--coral-line); gap: 2px; }\n.segmento button { border: 0; background: transparent; padding: clamp(6px, 1vh, 9px) clamp(10px, 1vw, 15px); border-radius: 10px; font-weight: 900; font-size: clamp(13px, 1.75vh, 16px); color: var(--ink-2); white-space: nowrap; transition: background 0.15s, color 0.15s; }\n.segmento button:hover { color: var(--coral-2); }\n.segmento button[aria-pressed=\"true\"] { background: var(--coral-2); color: #fff; box-shadow: 0 4px 10px rgba(224, 46, 74, 0.3); }\n.campos { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(10px, 1.2vw, 16px); }\n.campo { display: grid; gap: 6px; min-width: 0; }\n.campo label { font-weight: 900; font-size: clamp(13px, 1.8vh, 16px); color: var(--ink); }\n.stepper { display: grid; grid-template-columns: clamp(34px, 3vw, 46px) minmax(0, 1fr) clamp(34px, 3vw, 46px); align-items: center; height: clamp(54px, 8.6vh, 82px); border-radius: 18px; background: var(--coral-wash); border: 2px solid var(--coral-line); overflow: hidden; transition: border-color 0.15s, background 0.15s; }\n.stepper:focus-within { border-color: var(--coral); background: #fff; }\n.stepper button { height: 100%; border: 0; background: transparent; font-family: var(--title); font-weight: 600; font-size: clamp(22px, 3.4vh, 32px); color: var(--coral-2); line-height: 1; touch-action: manipulation; }\n.stepper button:hover { background: rgba(242, 64, 90, 0.08); }\n.stepper button:active { background: rgba(242, 64, 90, 0.16); }\n.stepper .valor { display: flex; align-items: baseline; justify-content: center; gap: 2px; min-width: 0; }\n.stepper .pre, .stepper .pos { font-family: var(--title); font-weight: 700; font-size: clamp(13px, 2vh, 18px); color: var(--coral-3); flex: none; }\n.stepper input { width: 100%; min-width: 0; border: 0; background: transparent; text-align: center; font-family: var(--title); font-weight: 800; font-size: clamp(24px, 4.2vh, 42px); color: var(--coral-2); padding: 0; font-variant-numeric: tabular-nums; }\n.stepper input:focus { outline: none; }\n.ajuda { font-size: clamp(11.5px, 1.5vh, 13.5px); font-weight: 700; color: var(--muted); }\n.sep { height: 1px; background: var(--line); }\n.alavancas { display: grid; gap: clamp(10px, 1.8vh, 16px); }\n.alavanca { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 16px; align-items: center; }\n.alavanca .nome { font-weight: 900; font-size: clamp(14px, 2vh, 18px); color: var(--ink); line-height: 1.2; }\n.alavanca .nome small { display: block; font-weight: 700; font-size: clamp(12px, 1.55vh, 14px); color: var(--muted); }\nbody:not(.modo-b) .so-b { display: none !important; }\nbody.modo-b .so-a { display: none !important; }\n\n.cta { border: 0; width: 100%; border-radius: 20px; padding: clamp(14px, 2.4vh, 22px) 18px; background: var(--coral-2); color: #fff; font-family: var(--title); font-weight: 800; font-size: clamp(16px, 2.6vh, 26px); letter-spacing: 0.06em; text-transform: uppercase; box-shadow: 0 8px 0 var(--coral-3), 0 18px 30px rgba(184, 31, 58, 0.3); transition: transform 0.08s, box-shadow 0.08s, background 0.15s; margin-bottom: 8px; }\n.cta:hover { background: var(--coral); }\n.cta:active { transform: translateY(6px); box-shadow: 0 2px 0 var(--coral-3), 0 8px 16px rgba(184, 31, 58, 0.3); }\n.nota { font-size: clamp(11px, 1.45vh, 13px); font-weight: 700; color: var(--muted); text-align: center; margin-top: -4px; }\n\n.tela { position: fixed; z-index: 3; top: max(14px, env(safe-area-inset-top, 0px)); right: max(16px, env(safe-area-inset-right, 0px)); border: 0; background: #fff; color: var(--ink); font-weight: 900; font-size: 14px; padding: 9px 16px; border-radius: 999px; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25); }\n.tela:hover { color: var(--coral-2); }\n.toast { position: fixed; z-index: 4; left: 50%; bottom: calc(22px + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%) translateY(16px); background: #fff; color: var(--ink); font-weight: 900; padding: 11px 20px; border-radius: 999px; box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3); opacity: 0; transition: opacity 0.2s, transform 0.2s; pointer-events: none; }\n.toast.on { opacity: 1; transform: translateX(-50%) translateY(0); }\n\n@media (max-height: 860px) and (min-width: 1081px) { .teclas { display: none; } .rotulo { margin-top: -4px; } }\n@media (max-width: 1080px), (max-aspect-ratio: 1/1) {\n  body { overflow: auto; }\n  .palco { height: auto; min-height: 100vh; grid-template-columns: minmax(0, 1fr); align-items: start; padding: 72px 18px 28px; }\n  .teclas { display: none; }\n}\n@media (max-width: 640px) {\n  .campos { grid-template-columns: minmax(0, 1fr); }\n  .alavanca { grid-template-columns: minmax(0, 1fr); }\n  .segmento { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); width: 100%; }\n  .segmento button { white-space: normal; padding: 8px 4px; font-size: 13px; line-height: 1.15; }\n  .grande { font-size: 64px; }\n  .tela { display: none; }\n  .fatos { flex-wrap: wrap; }\n}\n@media (prefers-reduced-motion: reduce) { .trilho i, .cta, .segmento button { transition: none; } }\n</style>\n</head>\n<body>\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <g id=\"estrela-forma\">\n      <path d=\"M95.7 0 L103.5 23 L129 23.8 L113.5 35.2 Q95.7 25 77.5 35.2 L63 23.6 L88 23 Z\"/>\n      <path d=\"M65 112.5 L127 112.5 Q128.6 112.5 129.2 114.2 L145 166 L96 135 L47 166 L62.8 114.2 Q63.4 112.5 65 112.5 Z\"/>\n    </g>\n  </defs>\n</svg>\n\n<div class=\"fundo\" aria-hidden=\"true\">\n  <svg class=\"estrela-a\" viewBox=\"0 0 192 166\"><use href=\"#estrela-forma\" fill=\"#f2405a\"/></svg>\n  <svg class=\"estrela-b\" viewBox=\"0 0 192 166\"><use href=\"#estrela-forma\" fill=\"#ffffff\"/></svg>\n</div>\n\n<button type=\"button\" class=\"tela\" id=\"tela\" aria-label=\"Tela cheia\">⛶ Tela cheia</button>\n\n<main class=\"palco\">\n  <section class=\"marca\" aria-live=\"polite\">\n    <svg class=\"logo\" viewBox=\"0 0 192 166\" role=\"img\" aria-label=\"Canal do Anfitrião\">\n      <g fill=\"#fff\">\n        <use href=\"#estrela-forma\"/>\n        <text x=\"96\" y=\"57\" text-anchor=\"middle\" font-family=\"Damion, 'Brush Script MT', cursive\" font-size=\"25\">Canal do</text>\n        <text x=\"96\" y=\"104\" text-anchor=\"middle\" font-family=\"Poppins, sans-serif\" font-weight=\"500\" font-size=\"45\" letter-spacing=\"-1.5\">Anfitrião</text>\n      </g>\n    </svg>\n    <div class=\"rotulo\">Calculadora de ganhos</div>\n    <h1>Quanto o seu imóvel pode <em>render a mais</em></h1>\n    <div class=\"resultado\">\n      <div class=\"grande\" id=\"ganho-mes\"><span class=\"mais\">+</span><span class=\"rs\">R$</span>0</div>\n      <div class=\"por\">por mês, com o que você aprende</div>\n    </div>\n    <div class=\"fatos\">\n      <div class=\"fato\"><b id=\"ganho-ano\">+R$ 0</b><span>por ano</span></div>\n      <div class=\"fato\"><b id=\"tres-anos\">+R$ 0</b><span>em 3 anos</span></div>\n      <div class=\"fato destaque\"><b id=\"paga\">—</b><span id=\"paga-r\">de ganho extra pagam o investimento</span></div>\n    </div>\n    <div class=\"barras\" aria-hidden=\"true\">\n      <div class=\"barra\"><span id=\"rot-hoje\">Hoje</span><div class=\"trilho\"><i class=\"base\" id=\"b-hoje\"></i></div><b id=\"fat-hoje\">R$ 0</b></div>\n      <div class=\"barra\"><span id=\"rot-novo\">Com os ajustes</span><div class=\"trilho\"><i class=\"base\" id=\"b-novo-base\"></i><i class=\"extra\" id=\"b-novo-extra\"></i></div><b id=\"fat-novo\">R$ 0</b></div>\n    </div>\n    <div class=\"teclas\"><span><kbd>F</kbd>tela cheia</span><span><kbd>Esc</kbd>sair</span><span><kbd>C</kbd>copiar simulação</span></div>\n  </section>\n\n  <section class=\"moldura\">\n    <div class=\"card\">\n      <div class=\"linha-topo\">\n        <h2>O seu imóvel<small class=\"so-a\">como está hoje</small><small class=\"so-b\">na temporada</small></h2>\n        <div class=\"segmento\" role=\"group\" aria-label=\"Situação do imóvel\">\n          <button type=\"button\" data-modo=\"a\" aria-pressed=\"true\">Já alugo por temporada</button>\n          <button type=\"button\" data-modo=\"b\" aria-pressed=\"false\">Aluguel fixo ou parado</button>\n        </div>\n      </div>\n\n      <div class=\"campos\">\n        <div class=\"campo\">\n          <label for=\"diaria\"><span class=\"so-a\">Diária média</span><span class=\"so-b\">Diária que espera</span></label>\n          <div class=\"stepper\"><button type=\"button\" data-passo=\"diaria:-10\" aria-label=\"Diminuir a diária\">−</button><div class=\"valor\"><span class=\"pre\">R$</span><input id=\"diaria\" inputmode=\"numeric\" autocomplete=\"off\" value=\"250\"></div><button type=\"button\" data-passo=\"diaria:10\" aria-label=\"Aumentar a diária\">+</button></div>\n          <span class=\"ajuda\">por noite</span>\n        </div>\n        <div class=\"campo\">\n          <label for=\"ocupacao\"><span class=\"so-a\">Taxa de ocupação</span><span class=\"so-b\">Ocupação que espera</span></label>\n          <div class=\"stepper\"><button type=\"button\" data-passo=\"ocupacao:-5\" aria-label=\"Menos ocupação\">−</button><div class=\"valor\"><input id=\"ocupacao\" inputmode=\"numeric\" autocomplete=\"off\" value=\"50\"><span class=\"pos\">%</span></div><button type=\"button\" data-passo=\"ocupacao:5\" aria-label=\"Mais ocupação\">+</button></div>\n          <span class=\"ajuda\" id=\"noites-ajuda\">15 noites por mês</span>\n        </div>\n        <div class=\"campo so-a\">\n          <label for=\"imoveis\">Imóveis</label>\n          <div class=\"stepper\"><button type=\"button\" data-passo=\"imoveis:-1\" aria-label=\"Menos imóveis\">−</button><div class=\"valor\"><input id=\"imoveis\" inputmode=\"numeric\" autocomplete=\"off\" value=\"1\"></div><button type=\"button\" data-passo=\"imoveis:1\" aria-label=\"Mais imóveis\">+</button></div>\n          <span class=\"ajuda\">com números parecidos</span>\n        </div>\n        <div class=\"campo so-b\">\n          <label for=\"fixo\">Aluguel fixo hoje</label>\n          <div class=\"stepper\"><button type=\"button\" data-passo=\"fixo:-100\" aria-label=\"Diminuir o aluguel\">−</button><div class=\"valor\"><span class=\"pre\">R$</span><input id=\"fixo\" inputmode=\"numeric\" autocomplete=\"off\" value=\"1800\"></div><button type=\"button\" data-passo=\"fixo:100\" aria-label=\"Aumentar o aluguel\">+</button></div>\n          <span class=\"ajuda\">por mês (0 se está parado)</span>\n        </div>\n      </div>\n\n      <div class=\"sep\"></div>\n\n      <div class=\"alavancas\">\n        <h2 style=\"font-size:clamp(17px,2.6vh,24px)\">Com o que você aprende<small>anúncio, preço certo, algoritmo e 5 estrelas</small></h2>\n        <div class=\"alavanca\">\n          <div class=\"nome\">Diária mais alta<small>anúncio que converte e preço certo</small></div>\n          <div class=\"segmento\" role=\"group\" aria-label=\"Aumento da diária\" id=\"seg-diaria\">\n            <button type=\"button\" data-v=\"0\" aria-pressed=\"false\">0%</button><button type=\"button\" data-v=\"5\" aria-pressed=\"false\">+5%</button><button type=\"button\" data-v=\"10\" aria-pressed=\"true\">+10%</button><button type=\"button\" data-v=\"15\" aria-pressed=\"false\">+15%</button><button type=\"button\" data-v=\"20\" aria-pressed=\"false\">+20%</button><button type=\"button\" data-v=\"30\" aria-pressed=\"false\">+30%</button>\n          </div>\n        </div>\n        <div class=\"alavanca\">\n          <div class=\"nome\">Ocupação maior<small>algoritmo e avaliações</small></div>\n          <div class=\"segmento\" role=\"group\" aria-label=\"Aumento da ocupação\" id=\"seg-ocupacao\">\n            <button type=\"button\" data-v=\"0\" aria-pressed=\"false\">0</button><button type=\"button\" data-v=\"5\" aria-pressed=\"true\">+5 pts</button><button type=\"button\" data-v=\"10\" aria-pressed=\"false\">+10 pts</button><button type=\"button\" data-v=\"15\" aria-pressed=\"false\">+15 pts</button><button type=\"button\" data-v=\"20\" aria-pressed=\"false\">+20 pts</button>\n          </div>\n        </div>\n      </div>\n\n      <button type=\"button\" class=\"cta\" id=\"copiar\">Copiar simulação pro lead</button>\n      <div class=\"nota\">Simulação com os números informados. Faturamento bruto, antes de taxas e custos. Não é promessa de resultado.</div>\n    </div>\n  </section>\n</main>\n\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n<script>\n(function () {\n  var params = new URLSearchParams(location.search);\n  var INVEST = Math.max(0, Number(params.get('investimento')) || 2997);\n  var $ = function (id) { return document.getElementById(id); };\n  var campos = { diaria: $('diaria'), ocupacao: $('ocupacao'), imoveis: $('imoveis'), fixo: $('fixo') };\n  var limites = { diaria: [0, 100000], ocupacao: [0, 100], imoveis: [1, 500], fixo: [0, 1000000] };\n  var modo = 'a', maisDiaria = 10, maisOcup = 5;\n  var brl = new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 });\n  var reduz = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function numero(s) { var n = Number(String(s).replace(/\\./g, '').replace(',', '.').replace(/[^\\d.]/g, '')); return isFinite(n) ? n : 0; }\n  function lim(k, v) { var l = limites[k]; return Math.min(l[1], Math.max(l[0], Math.round(v))); }\n  function ler(k) { return lim(k, numero(campos[k].value)); }\n  function moeda(v) { return 'R$ ' + brl.format(Math.round(v)); }\n  function mostra(k) { campos[k].value = (k === 'diaria' || k === 'fixo') ? brl.format(ler(k)) : String(ler(k)); }\n\n  ['diaria', 'ocupacao', 'imoveis', 'fixo'].forEach(function (k) { if (params.has(k)) campos[k].value = params.get(k); mostra(k); });\n  if (params.has('mais_diaria')) maisDiaria = Number(params.get('mais_diaria')) || 0;\n  if (params.has('mais_ocupacao')) maisOcup = Number(params.get('mais_ocupacao')) || 0;\n  if (params.get('modo') === 'b') modo = 'b';\n\n  // o número grande sobe animado (\"o dinheirinho subindo\")\n  var atual = {};\n  function anima(id, alvo, fmt) {\n    var de = atual[id] == null ? 0 : atual[id];\n    atual[id] = alvo;\n    var el = $(id);\n    if (reduz || de === alvo) { el.innerHTML = fmt(alvo); return; }\n    var t0 = null, dur = 700;\n    (function passo(t) {\n      if (t0 === null) t0 = t;\n      var k = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - k, 3);\n      el.innerHTML = fmt(de + (alvo - de) * e);\n      if (k < 1 && atual[id] === alvo) requestAnimationFrame(passo);\n    })(performance.now());\n  }\n  function prazo(dias) {\n    if (!isFinite(dias) || dias <= 0) return '—';\n    if (dias <= 60) { var d = Math.ceil(dias); return d + (d === 1 ? ' dia' : ' dias'); }\n    var m = dias / 30;\n    return (m < 10 ? m.toLocaleString('pt-BR', { maximumFractionDigits: 1 }) : Math.round(m)) + ' meses';\n  }\n  function marca(seg, v) { seg.querySelectorAll('button').forEach(function (b) { b.setAttribute('aria-pressed', String(Number(b.dataset.v) === v)); }); }\n\n  function link() {\n    var q = new URLSearchParams({ modo: modo, diaria: ler('diaria'), ocupacao: ler('ocupacao'), mais_diaria: maisDiaria, mais_ocupacao: maisOcup });\n    if (modo === 'a') q.set('imoveis', ler('imoveis')); else q.set('fixo', ler('fixo'));\n    if (params.has('investimento')) q.set('investimento', INVEST);\n    return q;\n  }\n\n  function calcula() {\n    var d = ler('diaria'), o = ler('ocupacao'), i = modo === 'a' ? ler('imoveis') : 1, f = ler('fixo');\n    var noites = o / 100 * 30, noitesNovo = Math.min(30, (o + maisOcup) / 100 * 30);\n    var novo = d * (1 + maisDiaria / 100) * noitesNovo * i;\n    var hoje = modo === 'a' ? d * noites * i : f;\n    var ganho = Math.max(0, novo - hoje), abaixo = novo < hoje;\n    $('noites-ajuda').textContent = (Math.round(noites * 10) / 10).toLocaleString('pt-BR') + ' noites por mês';\n    anima('ganho-mes', ganho, function (v) { return '<span class=\"mais\">+</span><span class=\"rs\">R$</span>' + brl.format(Math.round(v)); });\n    anima('ganho-ano', ganho * 12, function (v) { return '+' + moeda(v); });\n    anima('tres-anos', ganho * 36, function (v) { return '+' + moeda(v); });\n    $('rot-hoje').textContent = modo === 'a' ? 'Hoje' : 'Aluguel fixo';\n    $('rot-novo').textContent = modo === 'a' ? 'Com os ajustes' : 'Na temporada';\n    $('fat-hoje').textContent = moeda(hoje) + '/mês';\n    $('fat-novo').textContent = moeda(novo) + '/mês';\n    var topo = Math.max(hoje, novo, 1);\n    $('b-hoje').style.width = (hoje / topo * 100) + '%';\n    $('b-novo-base').style.width = (Math.min(hoje, novo) / topo * 100) + '%';\n    $('b-novo-extra').style.width = (ganho / topo * 100) + '%';\n    $('paga').textContent = abaixo ? 'Ajuste os números' : prazo(ganho > 0 ? INVEST / (ganho / 30) : Infinity);\n    $('paga-r').textContent = abaixo ? 'a temporada ficou abaixo do fixo' : 'de ganho extra pagam o investimento';\n    history.replaceState(null, '', location.pathname + '?' + link().toString());\n  }\n\n  function aplicaModo(m) {\n    modo = m;\n    document.body.classList.toggle('modo-b', m === 'b');\n    document.querySelectorAll('[data-modo]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.dataset.modo === m)); });\n    calcula();\n  }\n\n  Object.keys(campos).forEach(function (k) {\n    campos[k].addEventListener('input', calcula);\n    campos[k].addEventListener('blur', function () { mostra(k); calcula(); });\n    campos[k].addEventListener('focus', function () { campos[k].select(); });\n  });\n  document.querySelectorAll('[data-passo]').forEach(function (b) {\n    var p = b.dataset.passo.split(':'), k = p[0], passo = Number(p[1]), t = null, r = null, repetiu = false;\n    function um() { campos[k].value = lim(k, ler(k) + passo); mostra(k); calcula(); }\n    b.addEventListener('click', function () { if (repetiu) { repetiu = false; return; } um(); });\n    // segurar o botão repete\n    b.addEventListener('pointerdown', function () { t = setTimeout(function () { repetiu = true; r = setInterval(um, 90); }, 450); });\n    ['pointerup', 'pointerleave', 'pointercancel'].forEach(function (ev) { b.addEventListener(ev, function () { clearTimeout(t); clearInterval(r); }); });\n  });\n  $('seg-diaria').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; maisDiaria = Number(b.dataset.v); marca(this, maisDiaria); calcula(); });\n  $('seg-ocupacao').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; maisOcup = Number(b.dataset.v); marca(this, maisOcup); calcula(); });\n  document.querySelectorAll('[data-modo]').forEach(function (b) { b.addEventListener('click', function () { aplicaModo(b.dataset.modo); }); });\n\n  function toast(t) { var el = $('toast'); el.textContent = t; el.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(function () { el.classList.remove('on'); }, 1800); }\n  function copia() {\n    var url = location.origin + location.pathname + '?' + link().toString();\n    var ok = function () { toast('Link da simulação copiado'); };\n    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(ok, function () { prompt('Copie o link:', url); });\n    else prompt('Copie o link:', url);\n  }\n  $('copiar').addEventListener('click', copia);\n\n  var tela = $('tela');\n  function telaCheia() {\n    if (document.fullscreenElement) document.exitFullscreen();\n    else if (document.documentElement.requestFullscreen) document.documentElement.requestFullscreen().catch(function () {});\n  }\n  tela.addEventListener('click', telaCheia);\n  document.addEventListener('fullscreenchange', function () { tela.textContent = document.fullscreenElement ? '✕ Sair da tela cheia' : '⛶ Tela cheia'; });\n  if (!document.documentElement.requestFullscreen) tela.style.display = 'none';\n  document.addEventListener('keydown', function (e) {\n    if (e.target.tagName === 'INPUT' || e.metaKey || e.ctrlKey || e.altKey) return;\n    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); telaCheia(); }\n    if (e.key === 'c' || e.key === 'C') { e.preventDefault(); copia(); }\n  });\n\n  marca($('seg-diaria'), maisDiaria);\n  marca($('seg-ocupacao'), maisOcup);\n  aplicaModo(modo);\n})();\n</script>\n</body>\n</html>\n";
export const COFRE_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#24757f\">\n<title>Cofre de Cases · Canal do Anfitrião</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700&family=Raleway:wght@400;500;600;700&family=Barlow:wght@400;600&display=swap\">\n<style>\n/* Cofre de Cases: histórias reais de anfitriões tiradas das transcrições do\n   canal, pra o vendedor achar o case parecido com o lead e dar play no trecho.\n   Visual do site do Anfitrião 5 Estrelas (coral, teal, Poppins, Raleway). */\n:root {\n  color-scheme: light;\n  --bg: #f6f6f6;\n  --card: #ffffff;\n  --ink: #333333;\n  --ink-2: #4a4a4a;\n  --muted: #69727d;\n  --line: #e8e8e8;\n  --line-2: #d9d9d9;\n  --coral: #e23d59;\n  --coral-dark: #c92e49;\n  --coral-wash: #fdeef1;\n  --teal: #24757f;\n  --teal-2: #2a8995;\n  --teal-light: #aadbe1;\n  --teal-wash: #eaf5f6;\n  --shadow: 0 10px 30px rgba(17, 24, 39, 0.06);\n  --title: \"Poppins\", \"Raleway\", system-ui, sans-serif;\n  --body: \"Raleway\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  --label: \"Barlow\", \"Raleway\", system-ui, sans-serif;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--body); font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }\nbutton, input, textarea { font: inherit; color: inherit; }\nbutton { cursor: pointer; }\na { color: inherit; }\n:focus-visible { outline: 3px solid var(--teal-light); outline-offset: 2px; border-radius: 8px; }\nmark { background: #ffe6a8; color: inherit; border-radius: 3px; padding: 0 1px; }\n\n.top { background: var(--teal); color: #fff; padding: max(12px, env(safe-area-inset-top, 0px)) max(20px, env(safe-area-inset-right, 0px)) 12px max(20px, env(safe-area-inset-left, 0px)); display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }\n.top img { height: 44px; width: auto; display: block; }\n.top img.icone { width: 44px; height: 44px; border-radius: 12px; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.18); }\n.top h1 { margin: 0; font-family: var(--title); font-weight: 600; font-size: 22px; line-height: 1.1; }\n.top h1 small { display: block; font-family: var(--body); font-weight: 500; font-size: 13.5px; color: rgba(255, 255, 255, 0.82); }\n.top nav { margin-left: auto; display: flex; gap: 8px; }\n.top nav a { text-decoration: none; font-weight: 600; font-size: 14px; padding: 7px 14px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.35); }\n.top nav a:hover { background: rgba(255, 255, 255, 0.12); }\n\n.wrap { max-width: 1480px; margin: 0 auto; padding: 0 max(20px, env(safe-area-inset-right, 0px)) 40px max(20px, env(safe-area-inset-left, 0px)); }\n.busca { padding: 22px 0 14px; display: grid; gap: 10px; }\n.campo { position: relative; }\n.campo input { width: 100%; height: 60px; border-radius: 18px; border: 2px solid var(--line-2); background: #fff; padding: 0 120px 0 54px; font-size: 19px; font-weight: 500; box-shadow: var(--shadow); }\n.campo input:focus { outline: none; border-color: var(--teal); }\n.campo .lupa { position: absolute; left: 20px; top: 50%; transform: translateY(-50%); font-size: 20px; color: var(--muted); pointer-events: none; }\n.campo .atalho { position: absolute; right: 16px; top: 50%; transform: translateY(-50%); font-size: 12.5px; color: var(--muted); border: 1px solid var(--line-2); border-radius: 6px; padding: 2px 7px; }\n.campo .limpar { position: absolute; right: 12px; top: 50%; transform: translateY(-50%); border: 0; background: var(--bg); border-radius: 999px; padding: 6px 12px; font-weight: 600; font-size: 13.5px; color: var(--ink-2); display: none; }\n.busca.tem .campo .limpar { display: block; }\n.busca.tem .campo .atalho { display: none; }\n.dica { font-size: 14px; color: var(--muted); display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; }\n.dica button { border: 1px dashed var(--line-2); background: transparent; border-radius: 999px; padding: 3px 10px; font-size: 13.5px; color: var(--ink-2); }\n.dica button:hover { border-color: var(--teal); color: var(--teal); }\n\n.filtros { display: grid; gap: 8px; padding: 8px 0 14px; }\n.grupo { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 10px; align-items: start; }\n.grupo > span { font-family: var(--label); font-weight: 600; font-size: 12.5px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); padding-top: 7px; }\n.chips { display: flex; flex-wrap: wrap; gap: 6px; }\n.chip { border: 1px solid var(--line-2); background: #fff; border-radius: 999px; padding: 5px 12px; font-size: 14px; font-weight: 600; color: var(--ink-2); display: inline-flex; gap: 6px; align-items: center; }\n.chip small { font-weight: 600; color: var(--muted); font-size: 12px; }\n.chip:hover { border-color: var(--teal); }\n.chip[aria-pressed=\"true\"] { background: var(--teal); border-color: var(--teal); color: #fff; }\n.chip[aria-pressed=\"true\"] small { color: var(--teal-light); }\n.chip.zero { opacity: 0.45; }\n.grupo.objecoes .chip[aria-pressed=\"true\"] { background: var(--coral); border-color: var(--coral); }\n.grupo.objecoes .chip[aria-pressed=\"true\"] small { color: #ffd2da; }\n.btn.toggle-filtros { display: none; }\n.grupo.extra { display: none; }\nbody.mais-filtros .grupo.extra { display: grid; }\n.mais { justify-self: start; border: 0; background: transparent; color: var(--teal); font-weight: 700; font-size: 14px; padding: 2px 0; }\n.mais:hover { text-decoration: underline; }\n\n.status { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 4px 0 12px; font-size: 14.5px; color: var(--muted); }\n.status b { color: var(--ink); font-family: var(--title); font-weight: 600; }\n\n.layout { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 22px; align-items: start; }\n.lista { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; align-content: start; }\n.vazio { grid-column: 1 / -1; padding: 40px 20px; text-align: center; color: var(--muted); background: #fff; border-radius: 18px; border: 1px dashed var(--line-2); }\n\n.case { background: var(--card); border-radius: 18px; border: 1px solid var(--line); box-shadow: var(--shadow); padding: 18px 20px 16px; display: grid; gap: 10px; align-content: start; scroll-margin-top: 16px; transition: border-color 0.2s, box-shadow 0.2s; }\n.case.destaque { border-color: var(--coral); box-shadow: 0 0 0 3px var(--coral-wash), var(--shadow); }\n.case .topo { display: flex; justify-content: space-between; gap: 10px; align-items: center; }\n.forca { font-family: var(--label); font-weight: 600; font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; padding: 3px 9px; border-radius: 6px; }\n.forca.A { background: var(--coral); color: #fff; }\n.forca.B { background: var(--teal); color: #fff; }\n.forca.C { background: var(--bg); color: var(--muted); }\n.onde { font-size: 13px; color: var(--muted); font-weight: 600; text-align: right; }\n.case h3 { margin: 0; font-family: var(--title); font-weight: 600; font-size: 18.5px; line-height: 1.25; }\n.case .quem { margin: 0; font-size: 14.5px; color: var(--ink-2); }\n.nums { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }\n.nums li { background: var(--teal-wash); color: var(--teal); font-weight: 700; font-size: 13.5px; padding: 4px 10px; border-radius: 8px; }\n.case blockquote { margin: 0; padding: 10px 14px; border-left: 3px solid var(--coral); background: var(--coral-wash); border-radius: 0 10px 10px 0; font-style: italic; font-size: 15px; color: var(--ink); }\n.tags { display: flex; flex-wrap: wrap; gap: 5px; }\n.tag { font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-2); color: var(--muted); }\n.tag.obj { border-color: #f3b4c0; color: var(--coral-dark); }\n.case details { font-size: 14.5px; color: var(--ink-2); }\n.case summary { cursor: pointer; font-weight: 700; color: var(--teal); font-size: 14px; }\n.case details p { margin: 6px 0 0; }\n.acoes { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 2px; }\n.btn { border: 0; border-radius: 999px; padding: 9px 16px; font-weight: 700; font-size: 14px; display: inline-flex; gap: 8px; align-items: center; text-decoration: none; }\n.btn.play { background: var(--coral); color: #fff; box-shadow: 0 6px 16px rgba(226, 61, 89, 0.25); }\n.btn.play:hover { background: var(--coral-dark); }\n.btn.leve { background: var(--bg); color: var(--ink-2); border: 1px solid var(--line-2); }\n.btn.leve:hover { border-color: var(--teal); color: var(--teal); }\n.btn.ok { background: var(--teal); color: #fff; }\n\n/* chat */\n.chat { position: sticky; top: 16px; height: calc(100vh - 32px); min-height: 480px; background: #fff; border-radius: 20px; border: 1px solid var(--line); box-shadow: var(--shadow); display: grid; grid-template-rows: auto minmax(0, 1fr) auto; overflow: hidden; }\n.chat header { background: var(--coral); color: #fff; padding: 14px 18px; display: flex; align-items: center; gap: 10px; }\n.chat header b { font-family: var(--title); font-weight: 600; font-size: 17px; display: block; line-height: 1.1; }\n.chat header small { font-size: 13px; color: rgba(255, 255, 255, 0.88); }\n.chat header .fechar { margin-left: auto; display: none; border: 0; background: rgba(255, 255, 255, 0.2); color: #fff; border-radius: 999px; width: 34px; height: 34px; font-size: 18px; }\n.msgs { overflow-y: auto; padding: 16px; display: grid; gap: 10px; align-content: start; }\n.msg { max-width: 92%; padding: 10px 14px; border-radius: 16px; font-size: 15px; line-height: 1.45; white-space: pre-wrap; overflow-wrap: anywhere; }\n.msg.eu { justify-self: end; background: var(--teal); color: #fff; border-bottom-right-radius: 4px; }\n.msg.ia { justify-self: start; background: var(--bg); border-bottom-left-radius: 4px; }\n.msg.ia .ref { display: inline-flex; align-items: center; gap: 4px; border: 0; background: var(--coral); color: #fff; border-radius: 999px; padding: 1px 10px; font-size: 13px; font-weight: 700; margin: 1px 0; white-space: nowrap; }\n.msg.ia .ref:hover { background: var(--coral-dark); }\n.msg.ia.digitando::after { content: \"▍\"; animation: pisca 1s steps(2) infinite; color: var(--coral); }\n@keyframes pisca { 50% { opacity: 0; } }\n.sugestoes { display: grid; gap: 6px; }\n.sugestoes button { text-align: left; border: 1px solid var(--line-2); background: #fff; border-radius: 12px; padding: 8px 12px; font-size: 14px; color: var(--ink-2); }\n.sugestoes button:hover { border-color: var(--coral); color: var(--coral-dark); }\n.boas-vindas { font-size: 14.5px; color: var(--ink-2); }\n.enviar { border-top: 1px solid var(--line); padding: 10px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: end; }\n.enviar textarea { resize: none; border: 1px solid var(--line-2); border-radius: 14px; padding: 10px 12px; min-height: 46px; max-height: 140px; font-size: 15px; }\n.enviar textarea:focus { outline: none; border-color: var(--teal); }\n.enviar button { height: 46px; border: 0; border-radius: 14px; background: var(--coral); color: #fff; font-weight: 700; padding: 0 16px; }\n.enviar button:disabled { opacity: 0.5; }\n.abrir-chat { display: none; }\n\n/* player */\ndialog { border: 0; padding: 0; border-radius: 20px; width: min(980px, calc(100vw - 24px)); max-height: calc(100vh - 24px); background: #fff; box-shadow: 0 30px 80px rgba(0, 0, 0, 0.35); }\ndialog::backdrop { background: rgba(15, 20, 25, 0.72); }\n.player { display: grid; gap: 0; }\n.player .video { position: relative; aspect-ratio: 16 / 9; background: #000; }\n.player iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }\n.player .info { padding: 16px 20px 20px; display: grid; gap: 10px; max-height: 42vh; overflow-y: auto; }\n.player h2 { margin: 0; font-family: var(--title); font-weight: 600; font-size: 19px; line-height: 1.25; }\n.player .meta { font-size: 13.5px; color: var(--muted); }\n.player .texto { font-size: 15px; color: var(--ink-2); background: var(--bg); border-radius: 12px; padding: 12px 14px; white-space: pre-wrap; }\n.player .outros { display: flex; flex-wrap: wrap; gap: 6px; }\n.player .fechar-x { position: absolute; top: 10px; right: 10px; z-index: 2; border: 0; width: 38px; height: 38px; border-radius: 50%; background: rgba(0, 0, 0, 0.6); color: #fff; font-size: 20px; }\n.player .aviso { font-size: 13px; color: var(--muted); }\n.toast { position: fixed; left: 50%; bottom: calc(24px + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%) translateY(20px); background: var(--ink); color: #fff; padding: 10px 18px; border-radius: 999px; font-weight: 600; font-size: 14px; opacity: 0; pointer-events: none; transition: opacity 0.2s, transform 0.2s; z-index: 50; }\n.toast.on { opacity: 1; transform: translateX(-50%) translateY(0); }\n\nfooter { max-width: 1480px; margin: 0 auto; padding: 0 20px calc(28px + env(safe-area-inset-bottom, 0px)); font-size: 13px; color: var(--muted); }\n\n@media (max-width: 1180px) {\n  .layout { grid-template-columns: minmax(0, 1fr); }\n  .chat { position: fixed; inset: 0; height: auto; min-height: 0; border-radius: 0; z-index: 40; display: none; padding-top: env(safe-area-inset-top, 0px); }\n  body.chat-on .chat { display: grid; }\n  .chat header .fechar { display: block; }\n  .abrir-chat { display: inline-flex; position: fixed; right: max(16px, env(safe-area-inset-right, 0px)); bottom: calc(16px + env(safe-area-inset-bottom, 0px)); z-index: 30; border: 0; border-radius: 999px; background: var(--coral); color: #fff; font-weight: 700; font-size: 15px; padding: 14px 20px; box-shadow: 0 12px 30px rgba(226, 61, 89, 0.4); }\n}\n@media (max-width: 760px) {\n  .top img { height: 36px; }\n  .top nav { margin-left: 0; }\n  .campo input { height: 54px; font-size: 17px; padding-right: 86px; }\n  .campo .atalho { display: none; }\n  .btn.toggle-filtros { display: inline-flex; justify-self: start; }\n  .filtros { display: none; }\n  body.filtros-on .filtros { display: grid; }\n  .grupo { grid-template-columns: minmax(0, 1fr); gap: 4px; }\n  .grupo > span { padding-top: 0; }\n  .chips { flex-wrap: nowrap; overflow-x: auto; padding-bottom: 4px; }\n  .chip { flex: none; }\n  .lista { grid-template-columns: minmax(0, 1fr); }\n}\n@media (prefers-reduced-motion: reduce) { .toast, .case { transition: none; } .msg.ia.digitando::after { animation: none; } }\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <img src=\"/marca/cda-icone.png\" alt=\"Canal do Anfitrião\" width=\"192\" height=\"192\" class=\"icone\">\n  <h1>Cofre de Cases<small id=\"sub\">histórias reais pra usar na call</small></h1>\n  <nav aria-label=\"Ferramentas do time\">\n    <a href=\"/roteiro-sales-call-nova\">Roteiro</a>\n    <a href=\"/calculadora\" target=\"_blank\" rel=\"noopener\">Calculadora</a>\n  </nav>\n</header>\n\n<div class=\"wrap\">\n  <section class=\"busca\" id=\"busca\">\n    <div class=\"campo\">\n      <span class=\"lupa\" aria-hidden=\"true\">⌕</span>\n      <input id=\"q\" type=\"search\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Busque por cidade, perfil, objeção, número…\" aria-label=\"Buscar case\">\n      <span class=\"atalho\" aria-hidden=\"true\">/</span>\n      <button type=\"button\" class=\"limpar\" id=\"limpar\">Limpar</button>\n    </div>\n    <div class=\"dica\"><span>Tente:</span>\n      <button type=\"button\" data-q=\"praia casal\">praia casal</button>\n      <button type=\"button\" data-q=\"esposa\">esposa</button>\n      <button type=\"button\" data-q=\"imóvel longe\">imóvel longe</button>\n      <button type=\"button\" data-q=\"largou clt\">largou CLT</button>\n      <button type=\"button\" data-q=\"kitnet\">kitnet</button>\n      <button type=\"button\" data-q=\"precificação baixa temporada\">precificação baixa temporada</button>\n    </div>\n    <button type=\"button\" class=\"btn leve toggle-filtros\" id=\"toggle-filtros\">Filtros</button>\n  </section>\n\n  <section class=\"filtros\" id=\"filtros\" aria-label=\"Filtros\"></section>\n\n  <div class=\"status\"><span id=\"contagem\"></span><span id=\"ordem\">Mais parecidos primeiro · alunos com número no topo</span></div>\n\n  <div class=\"layout\">\n    <main class=\"lista\" id=\"lista\" aria-live=\"polite\"></main>\n\n    <aside class=\"chat\" id=\"chat\" aria-label=\"Pergunte ao cofre\">\n      <header>\n        <span aria-hidden=\"true\" style=\"font-size:22px\">✦</span>\n        <div><b>Pergunte ao cofre</b><small>Conte como é o lead e eu acho o case</small></div>\n        <button type=\"button\" class=\"fechar\" id=\"fechar-chat\" aria-label=\"Fechar o chat\">✕</button>\n      </header>\n      <div class=\"msgs\" id=\"msgs\">\n        <div class=\"boas-vindas\">Ex.: “lead tem 1 apê na praia, acha caro e precisa falar com a esposa”. Eu indico os cases certos, com a fala pra usar.</div>\n        <div class=\"sugestoes\" id=\"sugestoes\">\n          <button type=\"button\">Lead tem 1 apartamento na praia e acha caro</button>\n          <button type=\"button\">Mora em SP e o imóvel é no interior, longe dele</button>\n          <button type=\"button\">Ainda não tem imóvel e tem medo de errar</button>\n          <button type=\"button\">Já fez curso e não deu certo</button>\n        </div>\n      </div>\n      <form class=\"enviar\" id=\"form-chat\">\n        <textarea id=\"pergunta\" rows=\"1\" placeholder=\"Descreva o lead ou peça um case…\" aria-label=\"Mensagem\"></textarea>\n        <button type=\"submit\" id=\"enviar\">Enviar</button>\n      </form>\n    </aside>\n  </div>\n</div>\n\n<button type=\"button\" class=\"abrir-chat\" id=\"abrir-chat\">✦ Pergunte ao cofre</button>\n\n<dialog id=\"player\" aria-label=\"Trecho do vídeo\">\n  <div class=\"player\">\n    <button type=\"button\" class=\"fechar-x\" id=\"fechar-player\" aria-label=\"Fechar\">✕</button>\n    <div class=\"video\" id=\"video\"></div>\n    <div class=\"info\">\n      <h2 id=\"p-titulo\"></h2>\n      <div class=\"meta\" id=\"p-meta\"></div>\n      <div class=\"acoes\" id=\"p-acoes\"></div>\n      <div class=\"outros\" id=\"p-outros\"></div>\n      <div class=\"texto\" id=\"p-texto\"></div>\n      <div class=\"aviso\" id=\"p-aviso\"></div>\n    </div>\n  </div>\n</dialog>\n\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n<footer>Como o cofre é organizado: tem histórias com resultado (cases), elogios de alunos e falas de autoridades do mercado (Airbnb, PriceLabs, Stays). Cada item tem a objeção que ele ajuda a derrubar, o perfil de quem fala, o tipo de imóvel, o problema resolvido e o tipo de prova. A força diz o quanto pesa na call. Nos cases: A é aluno com número de antes e depois; B é história com número, mas de quem não é aluno (ou do Rômulo); C é menção curta. Nos elogios: A é elogio específico de aluno com resultado ou de autoridade; B é elogio claro; C é menção de passagem.</footer>\n\n<script id=\"dados\" type=\"application/json\">__COFRE_DADOS__</script>\n<script>\n(function () {\n  var D = JSON.parse(document.getElementById('dados').textContent);\n  var CASES = D.cases, GRUPOS = D.grupos, FORCA = D.forca, SIN = D.sinonimos;\n  var $ = function (id) { return document.getElementById(id); };\n  var PARADAS = { de: 1, da: 1, do: 1, das: 1, dos: 1, que: 1, com: 1, pra: 1, para: 1, um: 1, uma: 1, no: 1, na: 1, em: 1, os: 1, as: 1, e: 1, o: 1, a: 1, lead: 1, tem: 1, ele: 1, ela: 1, quer: 1, mas: 1, se: 1, nao: 1 };\n\n  function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9$]+/g, ' ').trim(); }\n  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }\n  function seg(h) { var p = String(h || '0').split(':').map(Number); while (p.length < 3) p.unshift(0); return p[0] * 3600 + p[1] * 60 + p[2]; }\n  function dur(c) { var d = Math.max(0, seg(c.trecho.fim) - seg(c.trecho.inicio)); return Math.floor(d / 60) + ':' + String(d % 60).padStart(2, '0'); }\n  function ytId(u) { var m = String(u || '').match(/(?:v=|youtu\\.be\\/|embed\\/)([\\w-]{6,})/); return m ? m[1] : null; }\n  function vimeoId(u) { var m = String(u || '').match(/vimeo\\.com\\/(?:video\\/)?(\\d+)/); return m ? m[1] : null; }\n  var ROTULO = {};\n  GRUPOS.forEach(function (g) { Object.keys(g.valores).forEach(function (v) { ROTULO[g.chave + ':' + v] = g.valores[v]; }); });\n  function rot(ch, v) { return ROTULO[ch + ':' + v] || v; }\n\n  // índice de busca: cada campo com um peso\n  CASES.forEach(function (c) {\n    var tags = [];\n    GRUPOS.forEach(function (g) { var vs = c[g.chave]; (Array.isArray(vs) ? vs : [vs]).forEach(function (v) { if (v) tags.push(rot(g.chave, v)); }); });\n    c._tags = {};\n    GRUPOS.forEach(function (g) { var vs = c[g.chave]; (Array.isArray(vs) ? vs : [vs]).forEach(function (v) { if (v) c._tags[v] = 1; }); });\n    c._campos = [\n      [norm([c.nome, c.titulo, c.cidade, c.uf].join(' ')), 5],\n      [norm(tags.join(' ')), 4],\n      [norm([c.quem, (c.numeros || []).join(' ')].join(' ')), 3],\n      [norm([c.antes, c.depois, c.citacao, c.como_usar].join(' ')), 2],\n      [norm([c.trecho && c.trecho.texto, (c.outros_trechos || []).map(function (o) { return o.sobre; }).join(' '), c.fonte && c.fonte.titulo].join(' ')), 1]\n    ];\n    c._ord = c.forca === 'A' ? 0 : c.forca === 'B' ? 1 : c.forca === 'C' ? 2 : 3;\n  });\n\n  var filtros = {}; // chave -> {valor: true}\n  var q = '';\n\n  function tokens(s) { return norm(s).split(' ').filter(function (t) { return t.length >= 2 && !PARADAS[t]; }); }\n  function pontua(c, toks) {\n    var score = 0, achou = 0;\n    toks.forEach(function (t) {\n      var re = new RegExp('(^| )' + t.replace(/[$]/g, '\\\\$'));\n      var s = 0;\n      c._campos.forEach(function (f) { if (re.test(f[0])) s += f[1]; });\n      (SIN[t] || []).forEach(function (tag) { if (c._tags[tag]) s += 4; });\n      if (s > 0) { achou++; score += s; }\n    });\n    return { score: score, achou: achou };\n  }\n  function passa(c, ignorar) {\n    return Object.keys(filtros).every(function (ch) {\n      if (ch === ignorar) return true;\n      var vs = Object.keys(filtros[ch]); if (!vs.length) return true;\n      var tem = Array.isArray(c[ch]) ? c[ch] : [c[ch]];\n      return vs.some(function (v) { return tem.indexOf(v) >= 0; });\n    });\n  }\n  function resultados() {\n    var toks = tokens(q);\n    var lista = [];\n    CASES.forEach(function (c) {\n      if (!passa(c)) return;\n      var p = toks.length ? pontua(c, toks) : { score: 0, achou: 0 };\n      if (toks.length && !p.achou) return;\n      lista.push({ c: c, p: p });\n    });\n    lista.sort(function (a, b) {\n      return (b.p.achou - a.p.achou) || (b.p.score - a.p.score) || (a.c._ord - b.c._ord) || String(b.c.fonte.data || '').localeCompare(String(a.c.fonte.data || ''));\n    });\n    return { lista: lista, toks: toks };\n  }\n\n  function realca(texto, toks) {\n    var s = esc(texto);\n    if (!toks.length) return s;\n    // realça palavras cujo começo (sem acento) bate com algum termo\n    return s.replace(/[A-Za-zÀ-ÿ0-9$]+/g, function (w) {\n      var n = norm(w);\n      return toks.some(function (t) { return n.indexOf(t) === 0; }) ? '<mark>' + w + '</mark>' : w;\n    });\n  }\n\n  var FORCA_ELOGIO = { A: 'Elogio específico, de quem pesa', B: 'Elogio claro', C: 'Menção de passagem' };\n  function forcaDica(c) { return (c.tipo === 'case' ? FORCA : FORCA_ELOGIO)[c.forca] || ''; }\n  function quemE(c) {\n    if (c.tipo === 'autoridade') return 'Autoridade';\n    var r = rot('aluno', c.aluno);\n    if (c.tipo !== 'elogio') return r;\n    return c.aluno === 'nao-informado' ? 'Elogio' : 'Elogio · ' + r;\n  }\n\n  function card(c, toks) {\n    var onde = [c.cidade, c.uf].filter(Boolean).join('/');\n    var objs = (c.objecoes || []).map(function (v) { return '<span class=\"tag obj\">' + esc(rot('objecoes', v)) + '</span>'; }).join('');\n    var perf = (c.perfil || []).concat(c.imovel || []).slice(0, 6).map(function (v) { return '<span class=\"tag\">' + esc(ROTULO['perfil:' + v] || ROTULO['imovel:' + v] || v) + '</span>'; }).join('');\n    var nums = (c.numeros || []).slice(0, 3).map(function (n) { return '<li>' + realca(n, toks) + '</li>'; }).join('');\n    var yt = c.fonte.tipo === 'youtube' && ytId(c.fonte.url);\n    return '<article class=\"case\" id=\"c-' + esc(c.id) + '\">' +\n      '<div class=\"topo\"><span class=\"forca ' + esc(c.forca) + '\" title=\"' + esc(forcaDica(c)) + '\">' + esc(c.forca) + ' · ' + esc(quemE(c)) + '</span><span class=\"onde\">' + esc(onde) + '</span></div>' +\n      '<h3>' + realca(c.titulo, toks) + '</h3>' +\n      '<p class=\"quem\"><b>' + realca(c.nome, toks) + '</b>' + (c.quem ? ' · ' + realca(c.quem, toks) : '') + '</p>' +\n      (nums ? '<ul class=\"nums\">' + nums + '</ul>' : '') +\n      (c.citacao ? '<blockquote>“' + realca(c.citacao, toks) + '”</blockquote>' : '') +\n      '<div class=\"tags\">' + objs + perf + '</div>' +\n      (c.como_usar || c.antes ? '<details><summary>Como usar na call</summary>' + (c.como_usar ? '<p>' + realca(c.como_usar, toks) + '</p>' : '') + (c.antes ? '<p><b>Antes:</b> ' + esc(c.antes) + '</p>' : '') + (c.depois ? '<p><b>Depois:</b> ' + esc(c.depois) + '</p>' : '') + '</details>' : '') +\n      '<div class=\"acoes\"><button type=\"button\" class=\"btn play\" data-play=\"' + esc(c.id) + '\">▶ Dar play · ' + dur(c) + '</button>' +\n      (yt ? '<button type=\"button\" class=\"btn leve\" data-copiar=\"' + esc(c.id) + '\">Copiar link pro lead</button>' : '') + '</div>' +\n      '</article>';\n  }\n\n  function desenhaFiltros() {\n    var html = GRUPOS.map(function (g) {\n      var chips = Object.keys(g.valores).map(function (v) {\n        var n = CASES.filter(function (c) { var t = Array.isArray(c[g.chave]) ? c[g.chave] : [c[g.chave]]; return t.indexOf(v) >= 0 && passa(c, g.chave); }).length;\n        var on = filtros[g.chave] && filtros[g.chave][v];\n        if (!n && !on) return '';\n        return '<button type=\"button\" class=\"chip' + (n ? '' : ' zero') + '\" data-f=\"' + g.chave + '\" data-v=\"' + esc(v) + '\" aria-pressed=\"' + (on ? 'true' : 'false') + '\">' + esc(g.valores[v]) + ' <small>' + n + '</small></button>';\n      }).join('');\n      var extra = g.chave !== 'tipo' && g.chave !== 'objecoes';\n      return chips ? '<div class=\"grupo ' + g.chave + (extra ? ' extra' : '') + '\"><span>' + esc(g.titulo) + '</span><div class=\"chips\">' + chips + '</div></div>' : '';\n    }).join('');\n    var ativosExtra = GRUPOS.some(function (g) { return g.chave !== 'tipo' && g.chave !== 'objecoes' && filtros[g.chave] && Object.keys(filtros[g.chave]).length; });\n    if (ativosExtra) document.body.classList.add('mais-filtros');\n    html += '<button type=\"button\" class=\"mais\" id=\"mais-filtros\">' + (document.body.classList.contains('mais-filtros') ? '− Menos filtros' : '+ Mais filtros: perfil, imóvel, problema, prova, quem é') + '</button>';\n    $('filtros').innerHTML = html;\n  }\n\n  function desenha() {\n    var r = resultados();\n    $('busca').classList.toggle('tem', !!q);\n    var ativos = Object.keys(filtros).reduce(function (s, ch) { return s + Object.keys(filtros[ch]).length; }, 0);\n    $('contagem').innerHTML = '<b>' + r.lista.length + '</b> ' + (r.lista.length === 1 ? 'case' : 'cases') + (q || ativos ? ' encontrados' : ' no cofre') + (ativos ? ' · ' + ativos + ' filtro' + (ativos > 1 ? 's' : '') : '');\n    $('lista').innerHTML = r.lista.length ? r.lista.map(function (x) { return card(x.c, r.toks); }).join('') :\n      '<div class=\"vazio\">Nenhum case com isso. Tire um filtro, troque a palavra ou pergunte ao cofre ao lado.</div>';\n    desenhaFiltros();\n  }\n\n  // busca em tempo real\n  $('q').addEventListener('input', function () { q = this.value; desenha(); salvaUrl(); });\n  $('limpar').addEventListener('click', function () { q = ''; $('q').value = ''; filtros = {}; desenha(); salvaUrl(); $('q').focus(); });\n  document.querySelectorAll('.dica button').forEach(function (b) { b.addEventListener('click', function () { q = b.dataset.q; $('q').value = q; desenha(); salvaUrl(); }); });\n  $('filtros').addEventListener('click', function (e) {\n    if (e.target.closest('#mais-filtros')) { document.body.classList.toggle('mais-filtros'); desenhaFiltros(); return; }\n    var b = e.target.closest('.chip'); if (!b) return;\n    var ch = b.dataset.f, v = b.dataset.v;\n    filtros[ch] = filtros[ch] || {};\n    if (filtros[ch][v]) delete filtros[ch][v]; else filtros[ch][v] = true;\n    desenha(); salvaUrl();\n  });\n  $('toggle-filtros').addEventListener('click', function () { document.body.classList.toggle('filtros-on'); });\n  document.addEventListener('keydown', function (e) {\n    if (e.key === '/' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') { e.preventDefault(); $('q').focus(); }\n  });\n\n  function salvaUrl() {\n    var p = new URLSearchParams();\n    if (q) p.set('q', q);\n    Object.keys(filtros).forEach(function (ch) { var vs = Object.keys(filtros[ch]); if (vs.length) p.set(ch, vs.join(',')); });\n    history.replaceState(null, '', location.pathname + (p.toString() ? '?' + p : ''));\n  }\n  (function leUrl() {\n    var p = new URLSearchParams(location.search);\n    q = p.get('q') || ''; $('q').value = q;\n    GRUPOS.forEach(function (g) { var v = p.get(g.chave); if (v) { filtros[g.chave] = {}; v.split(',').forEach(function (x) { filtros[g.chave][x] = true; }); } });\n  })();\n\n  // player no trecho\n  var porId = {}; CASES.forEach(function (c) { porId[c.id] = c; });\n  function linkLead(c, ini) { var id = ytId(c.fonte.url); return id ? 'https://youtu.be/' + id + '?t=' + ini : c.fonte.url; }\n  function toca(c, ini, fim) {\n    var yt = c.fonte.tipo === 'youtube' && ytId(c.fonte.url);\n    var vm = !yt && vimeoId(c.fonte.url);\n    var src = yt ? 'https://www.youtube-nocookie.com/embed/' + yt + '?start=' + ini + '&end=' + fim + '&autoplay=1&rel=0&modestbranding=1&playsinline=1'\n      : vm ? 'https://player.vimeo.com/video/' + vm + '?autoplay=1#t=' + ini + 's' : '';\n    $('video').innerHTML = src ? '<iframe src=\"' + esc(src) + '\" allow=\"autoplay; encrypted-media; picture-in-picture; fullscreen\" allowfullscreen title=\"' + esc(c.titulo) + '\"></iframe>' : '';\n  }\n  function abre(id, ini, fim) {\n    var c = porId[id]; if (!c) return;\n    var s = ini != null ? ini : seg(c.trecho.inicio), e = fim != null ? fim : seg(c.trecho.fim);\n    toca(c, s, e);\n    $('p-titulo').textContent = c.titulo;\n    $('p-meta').textContent = c.nome + (c.cidade ? ' · ' + [c.cidade, c.uf].filter(Boolean).join('/') : '') + ' · ' + c.fonte.titulo + ' · trecho ' + c.trecho.inicio + '–' + c.trecho.fim;\n    var yt = c.fonte.tipo === 'youtube' && ytId(c.fonte.url);\n    $('p-acoes').innerHTML =\n      '<button type=\"button\" class=\"btn play\" data-replay=\"' + esc(id) + '\" data-i=\"' + s + '\" data-f=\"' + e + '\">↺ Ver de novo</button>' +\n      (yt ? '<button type=\"button\" class=\"btn leve\" data-copiar=\"' + esc(id) + '\" data-i=\"' + s + '\">Copiar link pro lead</button>' : '') +\n      '<a class=\"btn leve\" target=\"_blank\" rel=\"noopener\" href=\"' + esc(yt ? 'https://www.youtube.com/watch?v=' + yt + '&t=' + s + 's' : c.fonte.url) + '\">' + (yt ? 'Abrir no YouTube' : 'Abrir na área de membros') + '</a>';\n    $('p-outros').innerHTML = (c.outros_trechos || []).map(function (o) {\n      return '<button type=\"button\" class=\"btn leve\" data-replay=\"' + esc(id) + '\" data-i=\"' + seg(o.inicio) + '\" data-f=\"' + seg(o.fim) + '\">▶ ' + esc(o.inicio.replace(/^00:/, '')) + ' · ' + esc(o.sobre) + '</button>';\n    }).join('');\n    $('p-texto').textContent = c.trecho.texto || '';\n    $('p-aviso').textContent = yt ? '' : 'Vídeo da área de membros: se não abrir aqui, use o botão pra abrir na área de membros (lead não tem acesso).';\n    if (!$('player').open) $('player').showModal();\n  }\n  function fecha() { $('video').innerHTML = ''; if ($('player').open) $('player').close(); }\n  $('fechar-player').addEventListener('click', fecha);\n  $('player').addEventListener('close', function () { $('video').innerHTML = ''; });\n  $('player').addEventListener('click', function (e) { if (e.target === this) fecha(); });\n\n  function toast(t) { var el = $('toast'); el.textContent = t; el.classList.add('on'); clearTimeout(toast._t); toast._t = setTimeout(function () { el.classList.remove('on'); }, 1800); }\n  function copia(id, ini) {\n    var c = porId[id]; if (!c) return;\n    var link = linkLead(c, ini != null ? ini : seg(c.trecho.inicio));\n    var feito = function () { toast('Link do trecho copiado'); };\n    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(link).then(feito, function () { prompt('Copie o link:', link); });\n    else prompt('Copie o link:', link);\n  }\n  document.addEventListener('click', function (e) {\n    var b = e.target.closest('[data-play],[data-replay],[data-copiar],[data-ref]'); if (!b) return;\n    if (b.dataset.play) abre(b.dataset.play);\n    else if (b.dataset.replay) abre(b.dataset.replay, Number(b.dataset.i), Number(b.dataset.f));\n    else if (b.dataset.copiar) copia(b.dataset.copiar, b.dataset.i != null ? Number(b.dataset.i) : null);\n    else if (b.dataset.ref) mostraCase(b.dataset.ref);\n  });\n\n  function mostraCase(id) {\n    if (!porId[id]) return;\n    var el = document.getElementById('c-' + id);\n    if (!el) { q = ''; $('q').value = ''; filtros = {}; desenha(); el = document.getElementById('c-' + id); }\n    if (window.matchMedia('(max-width: 1180px)').matches) document.body.classList.remove('chat-on');\n    document.querySelectorAll('.case.destaque').forEach(function (x) { x.classList.remove('destaque'); });\n    if (el) { el.classList.add('destaque'); el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }\n  }\n\n  // chat\n  var historico = [];\n  var ocupado = false;\n  function formata(texto, final) {\n    var s = esc(texto).replace(/\\*\\*(.+?)\\*\\*/g, '<b>$1</b>');\n    return s.replace(/\\[\\[([a-z0-9-]+)\\]\\]/g, function (m, id) {\n      var c = porId[id];\n      if (!c) return final ? '' : m;\n      return '<button type=\"button\" class=\"ref\" data-ref=\"' + id + '\">' + esc(c.nome) + '</button> <button type=\"button\" class=\"ref\" data-play=\"' + id + '\">▶</button>';\n    });\n  }\n  function bolha(quem, html) { var d = document.createElement('div'); d.className = 'msg ' + quem; d.innerHTML = html; $('msgs').appendChild(d); $('msgs').scrollTop = $('msgs').scrollHeight; return d; }\n  async function pergunta(texto) {\n    texto = String(texto || '').trim();\n    if (!texto || ocupado) return;\n    ocupado = true; $('enviar').disabled = true;\n    var sug = $('sugestoes'); if (sug) sug.remove();\n    bolha('eu', esc(texto));\n    historico.push({ role: 'user', content: texto });\n    var b = bolha('ia digitando', '');\n    var resposta = '';\n    try {\n      var r = await fetch('/cofre/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mensagens: historico.slice(-12) }) });\n      if (!r.ok || !r.body) {\n        var j = await r.json().catch(function () { return {}; });\n        throw new Error(j.error || ('Erro ' + r.status));\n      }\n      var leitor = r.body.getReader(), dec = new TextDecoder();\n      while (true) {\n        var x = await leitor.read(); if (x.done) break;\n        resposta += dec.decode(x.value, { stream: true });\n        b.innerHTML = formata(resposta, false);\n        $('msgs').scrollTop = $('msgs').scrollHeight;\n      }\n      b.innerHTML = formata(resposta, true);\n      historico.push({ role: 'assistant', content: resposta });\n    } catch (err) {\n      b.textContent = 'Não consegui responder agora (' + err.message + '). Tente de novo em instantes.';\n      historico.pop();\n    }\n    b.classList.remove('digitando');\n    ocupado = false; $('enviar').disabled = false;\n  }\n  $('form-chat').addEventListener('submit', function (e) { e.preventDefault(); var t = $('pergunta').value; $('pergunta').value = ''; $('pergunta').style.height = ''; pergunta(t); });\n  $('pergunta').addEventListener('keydown', function (e) { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); $('form-chat').requestSubmit(); } });\n  $('pergunta').addEventListener('input', function () { this.style.height = 'auto'; this.style.height = Math.min(140, this.scrollHeight) + 'px'; });\n  document.querySelectorAll('#sugestoes button').forEach(function (b) { b.addEventListener('click', function () { pergunta(b.textContent); }); });\n  $('abrir-chat').addEventListener('click', function () { document.body.classList.add('chat-on'); setTimeout(function () { $('pergunta').focus(); }, 50); });\n  $('fechar-chat').addEventListener('click', function () { document.body.classList.remove('chat-on'); });\n\n  var nCases = CASES.filter(function (c) { return c.tipo === 'case'; }).length;\n  $('sub').textContent = nCases + ' histórias e ' + (CASES.length - nCases) + ' elogios reais pra usar na call';\n  desenha();\n})();\n</script>\n</body>\n</html>\n";
